  ["denofnalorakk"] = {
    { pos = 1, community = true, source = "keystone.guru", author = "alexandros_theroman", url = "https://keystone.guru/route/den-of-nalorakk/r9yP5t2/skandar-tank-den-of-nalorakk-season-2-10-to-15", title = "Skandar Tank - Den of Nalorakk Season 2 (+10 to +15)", views = 158592, name = "Skandar Tank - Den of Nalorakk Season 2 (+10 to +15)", code = "!~MDT2~", pct = 100.1, pulls = { { f = 13.0, m = { 3, 4, 17, 4, 15, 2, 1, 1, 2, 1, 4, 1, 24, 1, 31, 1 }, c = { 1, 3, 2, 3, 3, 5, 3, 6, 3, 4, 3, 3, 4, 5, 15, 12, 15, 13, 17, 2, 17, 3, 17, 4, 17, 5, 24, 1, 31, 1 }, w = 1, ne = { "TANK PLANT HERE!", "FIRST OFFERING / OPENING\nYou could CC the Keen-Eyed Striker with Incap / Imprison / Sap to collect the first offering cleanly, or simply pull it with the opening pack. If you do that, remember to pull extra pack in the snow area. This route goes LEFT.", "EARTHWHISPER TENDERS\nPriority interrupt Healing Breath. Use grips / displacement / LoS to stack Tenders and Thornclaw Gatherers into the main pack.", "SPIRIT OF HUNGER\nSwap immediately to Starvation Effigy. Kill it before Insatiable Hunger completes or the party loses maximum health. Curse-dispel if it gets through.", "BL first pull" }, nz = { "坦克站这里！", "第一个贡品 / 开局\n可以用瘫痪/禁锢/闷棍控住锐眼掠击鹰，干净地拿第一个贡品，或者直接跟开局那波一起拉。这样的话记得在雪地区多拉一波。这条路线走左边。", "地语看护者\n优先打断 Healing Breath。用拉人/位移/卡视角把看护者和棘爪收集者聚进大波里。", "饥渴之灵\n立刻转火饥荒雕像。在 Insatiable Hunger 读完前杀掉，否则全队会掉最大生命值。漏了就驱散诅咒。", "第一波开嗜血" }, np = { 124.8, 347.4, 50.8, 348.5, 128.9, 309.2, 76.5, 335.9, 56.8, 323.9 } }, { f = 4.7, m = { 3, 4, 2, 2 }, c = { 3, 7, 3, 8, 3, 10, 3, 9, 2, 5, 2, 6 }, w = 2 }, { f = 6.2, m = { 15, 4, 2, 1, 3, 1, 24, 1, 1, 1, 4, 1 }, c = { 2, 9, 3, 16, 24, 7, 1, 5, 4, 3, 15, 6, 15, 8, 15, 9, 15, 7 }, w = 3 }, { f = 3.7, m = { 15, 4, 2, 1, 3, 1, 4, 1, 17, 1 }, c = { 2, 8, 3, 15, 4, 7, 15, 4, 15, 5, 15, 16, 15, 17, 17, 1 }, w = 4, ne = { "Wait for Spirit of Hunger to pass - DO NOT PULL THAT PATROL !", "TANK plant here - position here - range tag  Keen Eyes Striker." }, nz = { "等饥渴之灵走过去 - 别拉那个巡逻！", "坦克站这里 - 定好位 - 远程开怪锐眼掠击鹰。" }, np = { 163.3, 437.0, 125.2, 420.8 } }, { f = 1.1, m = { 15, 2, 4, 1, 16, 1 }, c = { 4, 8, 15, 18, 15, 19, 16, 1 }, w = 5, ne = { "Skip g20 Spirit of Hunger - stay close to left wall", "Bring one small pack into boss fight - make sure you do not pull Spirit of Hunger! Careful!", "HOARDMONGER Position the boss near one pile. \nRecommended empowerment order: Bones → Mushrooms → Meat. Face Earthshatter/Bonespike Slam away, clear Rotten Mushrooms, and save defensives for the late empowered roar." }, nz = { "跳过 g20 饥渴之灵 - 贴着左边墙走", "带一小波怪进 boss 战 - 千万别拉到饥渴之灵！小心！", "HOARDMONGER 把 boss 拉到其中一堆旁边。\n推荐强化顺序：骨头 → 蘑菇 → 肉。Earthshatter/骨刺猛击朝外放，清掉 Rotten Mushrooms，减伤留给后期强化的咆哮。" }, np = { 187.0, 392.0, 240.6, 377.5, 267.4, 416.1 } }, { f = 6.3, m = { 3, 5, 2, 2, 17, 1 }, c = { 3, 17, 3, 18, 3, 21, 3, 19, 3, 20, 2, 10, 2, 12, 17, 12 }, w = 6 }, { f = 7.5, m = { 15, 6, 4, 3, 6, 2, 17, 2, 7, 1 }, c = { 4, 12, 4, 14, 4, 15, 6, 17, 6, 18, 7, 8, 17, 13, 17, 16, 15, 27, 15, 26, 15, 25, 15, 24, 15, 28, 15, 29 }, w = 7, ne = { "BL HERE. BLOODLUST OPTION #1\nLarge gather after Boss 1 and before the ice section gives a big chunk of %. BL is strong here, but route/Lust timing may change with further testing.", "BIG BEAR GATHER\nTerritorial Matriarchs move VERY quickly while gathering. Keep mitigation active and avoid exposing your back. Soothe Mother's Wrath after the Curious Yearlings die." }, nz = { "这里开嗜血。嗜血方案 #1\n一号 boss 之后、冰区之前的大集合能拿一大截进度。这里嗜血很强，但路线/嗜血时机可能随后续测试调整。", "熊大集合\n领地主母在集合时移动非常快。保持减伤，别把背露出来。好奇的幼崽死后安抚掉 Mother's Wrath。" }, np = { 553.9, 408.0, 560.2, 375.3 } }, { f = 7.8, m = { 6, 5, 8, 2, 7, 1, 9, 1 }, c = { 6, 1, 6, 2, 6, 15, 6, 16, 6, 14, 7, 1, 8, 1, 8, 2, 9, 1 }, w = 8, ne = { "ENDURING WINTER\nFight inside the sheltered areas to avoid Harsh Winds. Tank Avatars at the edge and aim Pulverize away from the group's limited safe space.", "GLACIAL TOMBS\nAvatar of Determination creates Glacial Tombs that root players. Swap and kill them immediately — especially before the next wind cycle." }, nz = { "Enduring Winter\n在避风区里打，躲开强风。决意化身拉到边缘坦，粉碎朝着远离团队有限安全区的方向。", "Glacial Tomb\n决意化身会放 Glacial Tomb 定身玩家。立刻转火打掉 — 尤其要赶在下一轮风之前。" }, np = { 451.2, 263.3, 474.7, 290.9 } }, { f = 6.4, m = { 6, 3, 9, 2, 8, 2 }, c = { 6, 6, 6, 7, 6, 8, 9, 5, 9, 4, 8, 5, 8, 6 }, w = 9 }, { f = 14.0, m = { 6, 2, 7, 1, 9, 1, 10, 1, 5, 1 }, c = { 6, 12, 6, 13, 7, 5, 9, 7, 10, 2, 5, 1 }, w = 10, ne = { "WINTER SQUALL\nKilling The Winter Squall permanently stops Harsh Winds. Safest route is to kill it separately; pulling nearby trash into the storm may work but needs careful positioning." }, nz = { "寒冬暴风雪\n杀掉寒冬暴风雪能永久停掉强风。最稳的是单独杀；把附近小怪拉进风暴里也许可行，但站位要很小心。" }, np = { 296.1, 212.2 } }, { f = 0.0, m = { 18, 1 }, c = { 18, 1 }, w = 11, ne = { "SENTINEL OF WINTER\nStack BEFORE every Raging Squall so the tornadoes spawn together. Then move the boss/group away as one instead of covering the arena with Squalls.", "SHIVERCORES / FROZEN TEMPEST\nBring boss to the first Shivercore and kill them ONE AT A TIME. Soak each Rimeshatter and keep a Snowdrift close to the boss for Frozen Tempest." }, nz = { "寒冬哨兵\n每次狂怒的飑风之前先集合，让龙卷风刷在一起。然后 boss 和团队一起整体移开，别让飑风铺满场地。", "Shivercore / 寒冰暴雨\n把 boss 拉到第一个 Shivercore 旁，一次只打一个。每个 Rimeshatter 都要吃掉，寒冰暴雨时让一个 Snowdrift 靠近 boss。" }, np = { 245.0, 129.5, 232.8, 175.4 } }, { f = 8.9, m = { 11, 3, 12, 2, 22, 1, 13, 1, 14, 1, 23, 1 }, c = { 11, 1, 11, 2, 11, 3, 12, 1, 12, 2, 22, 1, 13, 1, 14, 1, 23, 1 }, w = 12, ne = { "FINAL AREA + NALORAKK\nUse grips/LoS to stack the ranged bridge packs; kill Magma Totems quickly. On Nalorakk, drop Echo clones on ONE edge, stack behind Zul'Jarra for Defensive Stance, tank soaks Forceful Slam alone, then intercept every red Echo charge." }, nz = { "最后区域 + 纳洛拉克\n用拉人/卡视角把桥上的远程怪聚起来；熔岩图腾尽快打掉。纳洛拉克：回响分身放在同一侧边缘，躲到祖尔加拉身后吃防御姿态，坦克单独吃强力猛击，然后拦截每一道红色回响冲锋。" }, np = { 692.7, 193.8 } }, { f = 7.8, m = { 14, 3, 23, 3, 11, 2, 12, 2 }, c = { 11, 4, 11, 5, 12, 3, 12, 4, 14, 2, 14, 3, 14, 4, 23, 2, 23, 3, 23, 4 }, w = 13 }, { f = 7.8, m = { 13, 2, 22, 2, 12, 1 }, c = { 13, 2, 13, 3, 22, 2, 22, 3, 12, 5 }, w = 14 }, { f = 4.8, m = { 21, 1, 25, 1, 26, 1, 27, 1 }, c = { 21, 1, 25, 1, 26, 1, 27, 1 }, w = 15 } }, titleZh = "Skandar 坦克 - 纳洛拉克的洞穴 第二赛季（+10~+15 层）", codeZh = "!~MDT2~" },
