    { pos = 4, community = true, source = "wago.io", author = "Tactyks", url = "https://wago.io/b69_rKkRL", title = "Tactyks PUG Friendly DEN OF NALORAKK M+ Route | Midnight Season 2", views = 900, name = "Tactyks PUG Friendly", code = "!~MDT2~", pct = 97.9, pulls = { { f = 8.3, m = { 3, 4, 1, 1, 2, 1, 17, 1, 24, 1 }, c = { 1, 3, 2, 3, 3, 4, 3, 3, 3, 5, 3, 6, 17, 2, 24, 1 }, w = 1, ne = { "Lust pull 1, pull 8 or 10, pull 15 (with pull 14) or Last boss" }, nz = { "嗜血时机：第 1 波、第 8 或 10 波、第 15 波（连同第 14 波）或最后一个 boss" }, np = { 48.4, 315.3 } }, { f = 3.9, m = { 15, 4, 4, 2, 2, 1, 3, 1 }, c = { 2, 8, 3, 15, 4, 4, 4, 7, 15, 11, 15, 10, 15, 16, 15, 17 }, w = 2 }, { f = 6.3, m = { 15, 4, 1, 1, 2, 1, 3, 1, 4, 1, 24, 1 }, c = { 1, 5, 2, 9, 3, 16, 4, 3, 15, 8, 15, 9, 15, 6, 15, 7, 24, 7 }, w = 3 }, { f = 8.8, m = { 3, 4, 17, 3, 2, 2, 15, 2, 4, 1 }, c = { 2, 6, 2, 5, 3, 10, 3, 9, 3, 7, 3, 8, 4, 8, 15, 18, 15, 19, 17, 9, 17, 10, 17, 8 }, w = 4, ne = { "Chain into upper pack when previous tenders are dead" }, nz = { "前面的看护者死了就连拉上面那波" }, np = { 224.7, 330.4 } }, { f = 0.0, m = { 16, 1 }, c = { 16, 1 }, w = 5 }, { f = 5.3, m = { 2, 2, 3, 2, 17, 2 }, c = { 2, 11, 2, 12, 3, 21, 3, 22, 17, 11, 17, 12 }, w = 6 }, { f = 5.0, m = { 6, 4, 4, 2 }, c = { 4, 15, 4, 14, 6, 1, 6, 2, 6, 17, 6, 18 }, w = 7 }, { f = 11.5, m = { 6, 3, 7, 3, 8, 2, 10, 1 }, c = { 6, 5, 6, 3, 6, 4, 7, 6, 7, 7, 7, 3, 8, 3, 8, 4, 10, 1 }, w = 8, ne = { "Missing terra rumbler in G45, replaced with G53 for count" }, nz = { "G45 少了撼地奔行者，用 G53 补进度" }, np = { 480.2, 174.9 } }, { f = 6.6, m = { 6, 3, 8, 2, 9, 2 }, c = { 6, 8, 6, 6, 6, 7, 8, 6, 8, 5, 9, 5, 9, 4 }, w = 9 }, { f = 14.3, m = { 6, 2, 5, 1, 7, 1, 9, 1, 10, 1 }, c = { 5, 1, 6, 13, 6, 12, 7, 5, 9, 7, 10, 2 }, w = 10 }, { f = 0.0, m = { 18, 1, 19, 1, 20, 1 }, c = { 18, 1, 19, 1, 20, 1 }, w = 11 }, { f = 6.2, m = { 12, 2, 11, 1, 13, 1, 22, 1 }, c = { 11, 1, 12, 1, 12, 2, 13, 1, 22, 1 }, w = 12 }, { f = 7.0, m = { 14, 3, 23, 3, 11, 2, 12, 1 }, c = { 11, 3, 11, 2, 12, 3, 