    { pos = 5, community = true, source = "wago.io", author = "Salatikue", url = "https://wago.io/CHXoW2QxlL", title = "ChillFlex", views = 108, name = "ChillFlex", code = "!~MDT2~", pct = 98.4, pulls = { { f = 9.2, m = { 3, 4, 1, 1, 2, 1, 17, 1, 24, 1, 31, 1 }, c = { 1, 3, 2, 3, 3, 3, 3, 4, 3, 6, 3, 5, 17, 2, 24, 1, 31, 1 }, w = 1 }, { f = 6.4, m = { 17, 3, 3, 2, 15, 2, 2, 1, 4, 1 }, c = { 2, 6, 3, 10, 3, 9, 4, 5, 15, 12, 15, 13, 17, 5, 17, 4, 17, 3 }, w = 2 }, { f = 7.5, m = { 17, 3, 15, 2, 1, 1, 4, 1, 24, 1 }, c = { 1, 7, 4, 8, 15, 18, 15, 19, 17, 10, 17, 8, 17, 9, 24, 5 }, w = 3 }, { f = 6.3, m = { 15, 4, 1, 1, 2, 1, 3, 1, 4, 1, 24, 1 }, c = { 1, 5, 2, 9, 3, 16, 4, 3, 15, 8, 15, 9, 15, 6, 15, 7, 24, 7 }, w = 4 }, { f = 0.0, m = { 16, 1 }, c = { 16, 1 }, w = 5 }, { f = 6.4, m = { 3, 5, 2, 2, 17, 1 }, c = { 2, 10, 2, 12, 3, 17, 3, 18, 3, 21, 3, 19, 3, 20, 17, 12 }, w = 6 }, { f = 7.1, m = { 6, 7, 4, 2 }, c = { 4, 15, 4, 14, 6, 18, 6, 17, 6, 1, 6, 2, 6, 15, 6, 16, 6, 14 }, w = 7 }, { f = 6.6, m = { 6, 3, 8, 2, 7, 1, 9, 1 }, c = { 6, 8, 6, 6, 6, 7, 7, 1, 8, 2, 8, 1, 9, 1 }, w = 8 }, { f = 5.9, m = { 6, 2, 8, 2, 9, 2 }, c = { 6, 13, 6, 12, 8, 6, 8, 5, 9, 5, 9, 4 }, w = 9 }, { f = 10.5, m = { 6, 3, 8, 2, 7, 1, 9, 1, 10, 1 }, c = { 6, 9, 6, 10, 6, 11, 7, 5, 8, 7, 8, 8, 9, 7, 10, 2 }, w = 10 }, { f = 7.0, m = { 5, 1 }, c = { 5, 1 }, w = 11 }, { f = 0.0, m = { 18, 1 }, c = { 18, 1 }, w = 12 }, { f = 6.4, m = { 11, 2, 13, 1, 14, 1, 22, 1, 23, 1 }, c = { 11, 2, 11, 3, 13, 1, 14, 1, 22, 1, 23, 1 }, w = 13, ne = { "Чтобы пропустить этот пак, прижмитесь справа к стене. Если случайно запуллилось - просто бейте все по пути." }, nz = { "想跳过这波怪，就贴着右边的墙走。如果不小心拉到了，就顺路全打掉。" }, np = { 725.3, 230.3 } }, { f = 7.9, m = { 14, 3, 23, 3, 11, 2, 12, 2 }, c = { 11, 4, 11, 5, 12, 3, 12, 4, 14, 2, 14, 3, 14, 4, 23, 2, 23, 3, 23, 4 }, w = 14 }, { f = 7.9, m = { 13, 2, 22, 2, 12, 1 }, c = { 12, 5, 13, 3, 13, 2, 22, 2, 22, 3 }, w = 15 }, { f = 4.9, m = { 21, 1 }, c = { 21, 1 }, w = 16 } }, titleZh = "ChillFlex", codeZh = "!~MDT2~" },
