  ["kingsrest"] = {
    { pos = 1, community = true, source = "keystone.guru", author = "alexandros_theroman", url = "https://keystone.guru/route/kings-rest/eMIO4TP/skandar-tank-kings-rest-10-to-15", title = "Skandar Tank - King's Rest (+10 to +15)", views = 85639, name = "Skandar Tank - King's Rest (+10 to +15)", code = "!~MDT2~", pct = 101.5, pulls = { { f = 0.0, m = { 2, 8 }, c = { 2, 1, 2, 2, 2, 3, 2, 4, 2, 5, 2, 7, 2, 8, 2, 6 }, w = 1, ne = { "OPENING — PURGE THE MINIONS\nPurge Bound by Shadow to kill Minions of Zul. Arcane Torrent / Mass Dispel / Pala Prot Bubble are excellent. Slow, stun or root Fixates — if one reaches you, expect a fear and maybe a wipe! :)\n\nYou can also pull them and ask the Team to wait in the initial corridor behind the corner, and walk back into the opening initial area.", "IMPORTANT:  Please note, you can skip the first 2 Animated Guardians and you can: Option 1: Bring those far 2 Guardians at the end of this room into the next room and BL there (into pull 3, with G5 and G6).  Just deal 2 Guardians in this room, and BL the next room (pull 3 and 4 together)." }, nz = { "开局 — 净化爪牙\n用净化术驱散“暗影之缚”来击杀祖尔的爪牙。奥术洪流 / 群体驱散 / 圣骑士保护祝福都很好用。对盯人的怪减速、晕或定身——一旦被追上，准备吃恐惧，可能直接灭团！:)\n\n也可以把它们拉起来，让队友在开头走廊拐角后面等着，再走回开局区域。", "重要：注意，前 2 个活化守卫可以跳过，你可以：方案 1：把这个房间尽头那 2 个远处的守卫带到下一个房间再开嗜血（并入第 3 波，和 G5、G6 一起）。这个房间只处理 2 个守卫，到下一个房间开嗜血（第 3 波和第 4 波一起拉）。" }, np = { 627.1, 301.7, 628.7, 344.2 } }, { f = 7.1, m = { 1, 2 }, c = { 1, 4, 1, 3 }, w = 2 }, { f = 10.5, m = { 5, 4, 4, 1, 3, 1 }, c = { 4, 1, 5, 8, 5, 7, 5, 1, 5, 6, 3, 4 }, w = 3, ne = { "You can chain or combine or pull together Pull 3 and 4 if your team is strong.", "OPENING — BLOODLUST 4 GUARDIANS\n2 guardians + pull 3 OR  pull 3 + pull 4.  Bloodlust + major CDs. Released Inhibitors gives huge Haste — plant and defensive; do not rely on kiting. Kick Hexer.", "GONG ROOM — HEXERS FIRST\nActivate the gong, focus Shadow-Borne Hexers and kick their dangerous casts. Safe route: main pull → chain the second pack in. Hit the Champion from behind during Vigilant Defense." }, nz = { "如果队伍够强，第 3 波和第 4 波可以连拉或一起拉。", "开局 — 嗜血打 4 个守卫\n2 个守卫 + 第 3 波，或者 第 3 波 + 第 4 波。嗜血 + 大招。“释放的抑制器”给巨额急速——站桩开减伤，别指望风筝。打断妖术师。", "锣房 — 先打妖术师\n敲锣后集火影裔妖术师，打断他们的危险读条。稳妥路线：主拉这波 → 连拉第二波。勇士开“警戒防御”时从背后打。" }, np = { 686.1, 459.4, 661.9, 395.0, 698.0, 382.5 } }, { f = 5.7, m = { 2, 5, 5, 2, 4, 1 }, c = { 4, 2, 5, 5, 5, 4, 2, 9, 2, 10, 2, 11, 2, 12, 2, 14 }, w = 4 }, { f = 0.0, m = { 38, 5, 6, 1 }, c = { 6, 1, 38, 3, 38, 4, 38, 5, 38, 2, 38, 1 }, w = 5, ne = { "GOLDEN SERPENT — STACK THE GOLD\nDrop Spit Gold pools together near one edge. On Lucre’s Call, move the boss away and hard-swap to Animated Gold. Roots, grips, knocks and Ring of Peace are excellent." }, nz = { "黄金风蛇 — 金子放一起\n吐金的水池集中放在一侧边缘。“财富召唤”时把 boss 拉开，全力转火活性黄金。定身、拉人、击退和平心之环都很好用。" }, np = { 750.6, 425.0 } }, { f = 29.7, m = { 10, 4, 14, 1, 15, 1, 11, 1, 12, 1, 13, 1, 9, 1, 7, 1, 8, 1 }, c = { 14, 1, 15, 1, 11, 1, 12, 1, 13, 1, 10, 1, 10, 2, 10, 3, 10, 4, 9, 1, 7, 1, 8, 1 }, w = 6, ne = { "ROYAL GAUNTLET — SAVE CDS FOR A’AKUL\nA’akul + Assassins is the dangerous wave. Expect multiple bleeds, including Mortal Bleed on the tank. Use strong defensives / bleed removals and do not combine with extra mobs." }, nz = { "皇家试炼 — 大招留给阿库尔\n阿库尔 + 刺客是危险的一波。会有多层流血，坦克身上还有“致命流血”。开强力减伤 / 驱流血，别再多带别的怪。" }, np = { 564.4, 544.6 } }, { f = 5.2, m = { 26, 7, 16, 1 }, c = { 16, 1, 26, 1, 26, 2, 26, 3, 26, 4, 26, 5, 26, 8, 26, 9 }, w = 7, ne = { "PURIFICATION CONSTRUCT — AIM TO THE EDGE\nPlace Purification Strike along the side of the bridge and gradually move forward. Party damage is significant — do not outrange your healer." }, nz = { "净化构造体 — 对准边缘\n把净化打击放在桥的边上，逐步往前推。全团伤害很高——别跑出治疗的距离。" }, np = { 415.8, 199.9 } }, { f = 5.0, m = { 26, 2, 37, 2, 17, 1 }, c = { 26, 7, 26, 6, 37, 2, 37, 1, 17, 1 }, w = 8, ne = { "EMBALMING ROOM — KICK THE MUMMIES\nWretched Discharge MUST be interrupted. For Entomb, watch for the shaking coffin and open the correct one. Wrong coffin = extra mummy + another dangerous cast." }, nz = { "防腐室 — 打断木乃伊\n恶疾排放必须打断。埋葬：留意哪个棺材在晃，打开正确的那个。开错棺材 = 多一只木乃伊 + 又一个危险读条。" }, np = { 520.6, 179.2 } }, { f = 6.0, m = { 26, 8, 37, 2, 17, 1 }, c = { 26, 10, 26, 12, 26, 13, 26, 14, 26, 15, 26, 16, 26, 17, 26, 11, 37, 3, 37, 4, 17, 2 }, w = 9 }, { f = 0.0, m = { 30, 1, 18, 1 }, c = { 30, 1, 18, 1 }, w = 10, ne = { "MCHIMBA — KEEP COFFINS CLEAR\nDrop Burn Corruption away from coffins. Free Entomb immediately and heal Drain Fluids targets above 90%. Be ready for Awakening Slam + extra mummies." }, nz = { "姆沁巴 — 棺材周围保持干净\n“燃烧腐蚀”放到远离棺材的地方。被埋葬的人立刻救出来，排干体液的目标血量奶到 90% 以上。准备好应对觉醒猛击 + 额外的木乃伊。" }, np = { 478.7, 129.5 } }, { f = 11.7, m = { 19, 2, 20, 2, 21, 2, 39, 1 }, c = { 19, 1, 19, 2, 20, 2, 20, 4, 21, 5, 21, 4, 39, 1 }, w = 11, ne = { "HALLS — SHAMANS ARE PRIORITY\nKill Spectral Shamans first and instantly destroy Healing Tide Totems. Prioritise Hex interrupts on Hex Priests. Avoid combining two Ghastly Brutes." }, nz = { "大厅 — 优先打萨满\n先杀幻影萨满祭司，治疗之潮图腾一出立刻打掉。优先打断妖术祭司的妖术。别把两只鬼魂蛮兵拉在一起。" }, np = { 328.9, 149.2 } }, { f = 9.1, m = { 21, 2, 23, 2, 22, 1, 39, 1, 19, 1 }, c = { 22, 1, 21, 2, 21, 6, 23, 5, 23, 6, 39, 2, 19, 3 }, w = 12, ne = { "A strong team can chain or combine pull 10 and pull 11", "SHAMANS ARE PRIORITY\nKill Spectral Shamans first and instantly destroy Healing Tide Totems." }, nz = { "强队可以连拉或合并第 10 波和第 11 波", "优先打萨满\n先杀幻影萨满祭司，治疗之潮图腾一出立刻打掉。" }, np = { 368.2, 297.2, 333.8, 231.5 } }, { f = 5.2, m = { 23, 2, 20, 1 }, c = { 23, 1, 23, 2, 20, 1 }, w = 13 }, { f = 0.0, m = { 28, 1, 29, 1, 34, 1, 35, 1, 36, 1, 27, 1 }, c = { 28, 1, 29, 1, 34, 1, 35, 1, 36, 1, 27, 1 }, w = 14, ne = { "COUNCIL — MECHANICS > DAMAGE\nKula: dodge axes. Aka’ali: group soak Barrel Through, then kite after Debilitating Backhand. Zanazal: kick Poison Nova and kill Explosive Totem FIRST." }, nz = { "议会 — 机制 > 伤害\n库拉：躲斧子。阿卡阿里：全队集合分摊翻滚，被“衰弱反手”之后风筝。扎纳扎尔：打断毒性新星，优先打爆裂图腾。" }, np = { 390.8, 471.8 } }, { f = 4.9, m = { 33, 1, 24, 1 }, c = { 33, 1, 24, 1 }, w = 15, ne = { "SHADOW OF ZUL — ASSIGN 2 SOAKERS\nAssign one player to each Pool of Darkness before the pull. Send Dark Revelation targets away in different directions, then purge/control the spawned Minions of Zul." }, nz = { "祖尔之影 — 安排 2 个人踩圈\n开怪前给每个黑暗之池安排一个人。黑暗启示的目标往不同方向散开，然后净化/控制刷出来的祖尔的爪牙。" }, np = { 220.9, 262.8 } }, { f = 0.0, m = { 31, 1, 32, 1, 25, 1 }, c = { 31, 1, 32, 1, 25, 1 }, w = 16, ne = { "DAZAR — KILL REBAN BEFORE 80%\nFocus Reban and kick Deathly Roar before pushing Dazar below 80%. Then rotate together around the room. Tank: face Searing Gold away and defensive Blade Combo + Savage Maul overlaps." }, nz = { "达萨 — 80% 前杀掉莱班\n集火莱班，打断致命咆哮，再把达萨打到 80% 以下。之后全队一起绕房间转。坦克：灼热黄金朝外，剑刃连击 + 野蛮重殴重叠时开减伤。" }, np = { 94.0, 257.0 } } }, titleZh = "Skandar 坦克 - 诸王之眠（+10~+15 层）", codeZh = "!~MDT2~" },
    { pos = 2, community = true, source = "keystone.guru", author = "alexandros_theroman", url = "https://keystone.guru/route/kings-rest/TdC9Aps/skandar-tank-kings-rest-high-keys-17-to-20", title = "Skandar Tank - King's Rest High Keys (+17 to +20)", views = 5556, name = "Skandar Tank - King's Rest High Keys (+17 to +20)", code = "!~MDT2~", pct = 101.0, pulls = { { f = 0.0, m = { 2, 8 }, c = { 2, 1, 2, 2, 2, 3, 2, 4, 2, 5, 2, 7, 2, 8, 2, 6 }, w = 1, ne = { "IMPORTANT:  Please note, you can skip the first 2 Animated Guardians and you can: Option 1: Bring those far 2 Guardians at the end of this room into the next room and BL there (into pull 3, with G5 and G6).  Just deal 2 Guardians in this room, and BL the next room (pull 3 and 4 together).", "After first boss, ask one fast DPS to go and pull in first corridor one of the Construct Guardians", "You can chain or combine or pull together Pull 3 and 4 if your team is strong." }, nz = { "重要：注意，前 2 个活化守卫可以跳过，你可以：方案 1：把这个房间尽头那 2 个远处的守卫带到下一个房间再开嗜血（并入第 3 波，和 G5、G6 一起）。这个房间只处理 2 个守卫，到下一个房间开嗜血（第 3 波和第 4 波一起拉）。", "打完一号 boss 后，让一个跑得快的 DPS 去第一条走廊把一个构造守卫拉过来", "如果队伍够强，第 3 波和第 4 波可以连拉或一起拉。" }, np = { 628.7, 344.2, 556.4, 359.1, 640.1, 359.8 } }, { f = 12.9, m = { 1, 2, 5, 2, 4, 1 }, c = { 1, 3, 1, 4, 4, 1, 5, 7, 5, 8 }, w = 2, ne = { "OPENING — BLOODLUST 4 GUARDIANS\n2 guardians + pull 3 OR  pull 3 + pull 4.  Bloodlust + major CDs. Released Inhibitors gives huge Haste — plant and defensive; do not rely on kiting. Kick Hexer.", "GONG ROOM — HEXERS FIRST\nActivate the gong, focus Shadow-Borne Hexers and kick their dangerous casts. Safe route: main pull → chain the second pack in. Hit the Champion from behind during Vigilant Defense." }, nz = { "开局 — 嗜血打 4 个守卫\n2 个守卫 + 第 3 波，或者 第 3 波 + 第 4 波。嗜血 + 大招。“释放的抑制器”给巨额急速——站桩开减伤，别指望风筝。打断妖术师。", "锣房 — 先打妖术师\n敲锣后集火影裔妖术师，打断他们的危险读条。稳妥路线：主拉这波 → 连拉第二波。勇士开“警戒防御”时从背后打。" }, np = { 661.9, 395.0, 698.0, 382.5 } }, { f = 10.6, m = { 2, 5, 5, 4, 4, 1, 3, 1 }, c = { 2, 9, 2, 10, 2, 11, 2, 12, 2, 14, 4, 2, 5, 4, 5, 5, 5, 1, 5, 6, 3, 4 }, w = 3 }, { f = 0.0, m = { 38, 5, 6, 1 }, c = { 6, 1, 38, 3, 38, 4, 38, 5, 38, 2, 38, 1 }, w = 4, ne = { "GOLDEN SERPENT — STACK THE GOLD\nDrop Spit Gold pools together near one edge. On Lucre’s Call, move the boss away and hard-swap to Animated Gold. Roots, grips, knocks and Ring of Peace are excellent." }, nz = { "黄金风蛇 — 金子放一起\n吐金的水池集中放在一侧边缘。“财富召唤”时把 boss 拉开，全力转火活性黄金。定身、拉人、击退和平心之环都很好用。" }, np = { 750.6, 425.0 } }, { f = 33.4, m = { 10, 4, 13, 1, 7, 1, 14, 1, 15, 1, 8, 1, 9, 1, 11, 1, 12, 1, 1, 1 }, c = { 13, 1, 7, 1, 14, 1, 15, 1, 8, 1, 9, 1, 10, 1, 10, 2, 10, 3, 10, 4, 11, 1, 12, 1, 1, 2 }, w = 5, ne = { "OPENING — PURGE THE MINIONS\nPurge Bound by Shadow to kill Minions of Zul. Arcane Torrent / Mass Dispel / Pala Prot Bubble are excellent. Slow, stun or root Fixates — if one reaches you, expect a fear and maybe a wipe! :)", "ROYAL GAUNTLET — SAVE CDS FOR A’AKUL\nA’akul + Assassins is the dangerous wave. Expect multiple bleeds, including Mortal Bleed on the tank. Use strong defensives / bleed removals and do not combine with extra mobs." }, nz = { "开局 — 净化爪牙\n用净化术驱散“暗影之缚”来击杀祖尔的爪牙。奥术洪流 / 群体驱散 / 圣骑士保护祝福都很好用。对盯人的怪减速、晕或定身——一旦被追上，准备吃恐惧，可能直接灭团！:)", "皇家试炼 — 大招留给阿库尔\n阿库尔 + 刺客是危险的一波。会有多层流血，坦克身上还有“致命流血”。开强力减伤 / 驱流血，别再多带别的怪。" }, np = { 611.8, 306.6, 562.0, 300.1 } }, { f = 12.2, m = { 26, 17, 37, 4, 17, 2 }, c = { 37, 3, 37, 4, 37, 1, 37, 2, 17, 2, 17, 1, 26, 10, 26, 12, 26, 13, 26, 14, 26, 15, 26, 16, 26, 17, 26, 11, 26, 4, 26, 1, 26, 2, 26, 8, 26, 9, 26, 5, 26, 3, 26, 6, 26, 7 }, w = 6, ne = { "EMBALMING ROOM — KICK THE MUMMIE. Start LEFT then pull right when Entomb cast begins. \n\nWretched Discharge MUST be interrupted. For Entomb, watch for the shaking coffin and open the correct one. Wrong coffin = extra mummy + another dangerous cast.", "PURIFICATION CONSTRUCT — AIM TO THE EDGE\nPlace Purification Strike along the side of the bridge and gradually move forward. Party damage is significant — do not outrange your healer." }, nz = { "防腐室 — 打断木乃伊。先拉左边，埋葬开始读条时再拉右边。\n\n恶疾排放必须打断。埋葬：留意哪个棺材在晃，打开正确的那个。开错棺材 = 多一只木乃伊 + 又一个危险读条。", "净化构造体 — 对准边缘\n把净化打击放在桥的边上，逐步往前推。全团伤害很高——别跑出治疗的距离。" }, np = { 520.6, 179.2, 459.3, 94.8 } }, { f = 0.0, m = { 18, 1, 30, 1 }, c = { 18, 1, 30, 1 }, w = 7, ne = { "MCHIMBA — KEEP COFFINS CLEAR\nDrop Burn Corruption away from coffins. Free Entomb immediately and heal Drain Fluids targets above 90%. Be ready for Awakening Slam + extra mummies." }, nz = { "姆沁巴 — 棺材周围保持干净\n“燃烧腐蚀”放到远离棺材的地方。被埋葬的人立刻救出来，排干体液的目标血量奶到 90% 以上。准备好应对觉醒猛击 + 额外的木乃伊。" }, np = { 478.7, 129.5 } }, { f = 11.7, m = { 20, 2, 21, 2, 19, 2, 39, 1 }, c = { 20, 2, 20, 4, 21, 5, 21, 4, 39, 1, 19, 1, 19, 2 }, w = 8, ne = { "HALLS — SHAMANS ARE PRIORITY\nKill Spectral Shamans first and instantly destroy Healing Tide Totems. Prioritise Hex interrupts on Hex Priests. Avoid combining two Ghastly Brutes." }, nz = { "大厅 — 优先打萨满\n先杀幻影萨满祭司，治疗之潮图腾一出立刻打掉。优先打断妖术祭司的妖术。别把两只鬼魂蛮兵拉在一起。" }, np = { 359.4, 103.8 } }, { f = 9.1, m = { 21, 2, 23, 2, 39, 1, 22, 1, 19, 1 }, c = { 21, 2, 21, 6, 39, 2, 22, 1, 19, 3, 23, 5, 23, 6 }, w = 9, ne = { "SHAMANS ARE PRIORITY\nKill Spectral Shamans first and instantly destroy Healing Tide Totems.", "A strong team can chain or combine pull 10 and pull 11" }, nz = { "优先打萨满\n先杀幻影萨满祭司，治疗之潮图腾一出立刻打掉。", "强队可以连拉或合并第 10 波和第 11 波" }, np = { 333.8, 231.5, 359.1, 217.9 } }, { f = 5.2, m = { 23, 2, 35, 1, 27, 1, 29, 1, 34, 1, 36, 1, 20, 1, 28, 1 }, c = { 35, 1, 27, 1, 29, 1, 34, 1, 36, 1, 20, 1, 23, 1, 23, 2, 28, 1 }, w = 10, ne = { "COUNCIL — MECHANICS > DAMAGE\nKula: dodge axes. Aka’ali: group soak Barrel Through, then kite after Debilitating Backhand. Zanazal: kick Poison Nova and kill Explosive Totem FIRST." }, nz = { "议会 — 机制 > 伤害\n库拉：躲斧子。阿卡阿里：全队集合分摊翻滚，被“衰弱反手”之后风筝。扎纳扎尔：打断毒性新星，优先打爆裂图腾。" }, np = { 360.6, 352.8 } }, { f = 4.9, m = { 24, 1, 33, 1 }, c = { 24, 1, 33, 1 }, w = 11, ne = { "SHADOW OF ZUL — ASSIGN 2 SOAKERS\nAssign one player to each Pool of Darkness before the pull. Send Dark Revelation targets away in different directions, then purge/control the spawned Minions of Zul." }, nz = { "祖尔之影 — 安排 2 个人踩圈\n开怪前给每个黑暗之池安排一个人。黑暗启示的目标往不同方向散开，然后净化/控制刷出来的祖尔的爪牙。" }, np = { 206.7, 281.0 } }, { f = 0.0, m = { 31, 1, 32, 1, 25, 1 }, c = { 31, 1, 32, 1, 25, 1 }, w = 12, ne = { "DAZAR — KILL REBAN BEFORE 80%\nFocus Reban and kick Deathly Roar before pushing Dazar below 80%. Then rotate together around the room. Tank: face Searing Gold away and defensive Blade Combo + Savage Maul overlaps." }, nz = { "达萨 — 80% 前杀掉莱班\n集火莱班，打断致命咆哮，再把达萨打到 80% 以下。之后全队一起绕房间转。坦克：灼热黄金朝外，剑刃连击 + 野蛮重殴重叠时开减伤。" }, np = { 95.2, 273.2 } } }, titleZh = "Skandar 坦克 - 诸王之眠 高层（+17~+20 层）", codeZh = "!~MDT2~" },
    { pos = 3, community = true, source = "keystone.guru", author = "elitzur", url = "https://keystone.guru/route/kings-rest/0S4viIA/elitzur-kr-1", title = "elitzur_kr_1", views = 11366, name = "elitzur_kr_1", code = "!~MDT2~", pct = 101.5, pulls = { { f = 12.8, m = { 2, 5, 1, 2, 5, 2, 4, 1 }, c = { 1, 3, 1, 4, 2, 12, 2, 9, 2, 10, 2, 14, 2, 11, 4, 1, 5, 7, 5, 8 }, w = 1, ne = { "Caster Comp: roar + invis skip.\nPhys Comp: roar + shroud skip.\nTake dbl golem into boss room, start RP and LUST!" }, nz = { "法系队：咆哮 + 隐身跳过。\n物理队：咆哮 + 潜伏帷幕跳过。\n把两个傀儡带进 boss 房，开剧情然后开嗜血！" }, np = { 640.1, 359.8 } }, { f = 10.5, m = { 38, 5, 5, 4, 4, 1, 6, 1, 3, 1 }, c = { 4, 2, 5, 1, 5, 4, 5, 5, 5, 6, 6, 1, 38, 1, 38, 2, 38, 3, 38, 4, 38, 5, 3, 4 }, w = 2 }, { f = 29.7, m = { 10, 4, 13, 1, 7, 1, 14, 1, 15, 1, 8, 1, 9, 1, 11, 1, 12, 1 }, c = { 13, 1, 7, 1, 14, 1, 15, 1, 8, 1, 9, 1, 10, 1, 10, 2, 10, 4, 10, 3, 11, 1, 12, 1 }, w = 3 }, { f = 4.1, m = { 16, 1 }, c = { 16, 1 }, w = 4, ne = { "LUST miniboss!" }, nz = { "小 boss 开嗜血！" }, np = { 460.7, 305.1 } }, { f = 6.2, m = { 26, 9, 37, 2, 17, 1 }, c = { 37, 1, 37, 2, 17, 1, 26, 7, 26, 1, 26, 2, 26, 4, 26, 8, 26, 9, 26, 5, 26, 3, 26, 6 }, w = 5 }, { f = 6.0, m = { 26, 8, 37, 2, 18, 1, 30, 1, 17, 1 }, c = { 37, 4, 37, 3, 18, 1, 26, 17, 26, 16, 26, 10, 26, 11, 26, 12, 26, 13, 26, 14, 26, 15, 30, 1, 17, 2 }, w = 6 }, { f = 11.7, m = { 20, 2, 19, 2, 21, 2, 39, 1 }, c = { 20, 2, 20, 4, 19, 1, 19, 2, 21, 5, 21, 4, 39, 1 }, w = 7 }, { f = 9.1, m = { 21, 2, 23, 2, 19, 1, 22, 1, 39, 1 }, c = { 19, 3, 21, 2, 21, 6, 22, 1, 23, 5, 23, 6, 39, 2 }, w = 8 }, { f = 5.2, m = { 23, 2, 27, 1, 28, 1, 29, 1, 34, 1, 35, 1, 36, 1, 20, 1 }, c = { 27, 1, 28, 1, 29, 1, 34, 1, 35, 1, 36, 1, 23, 1, 23, 2, 20, 1 }, w = 9 }, { f = 4.9, m = { 25, 1, 31, 1, 32, 1, 33, 1, 24, 1 }, c = { 25, 1, 31, 1, 32, 1, 33, 1, 24, 1 }, w = 10, ne = { "LUST last boss!" }, nz = { "最后一个 boss 开嗜血！" }, np = { 153.7, 273.2 } } }, titleZh = "elitzur_kr_1", codeZh = "!~MDT2~" },
    { pos = 4, community = true, source = "wago.io", author = "Tactyks", url = "https://wago.io/U22_Bys16", title = "Tactyks PUG Friendly KINGS' REST M+ Route | Midnight Season 2", views = 689, name = "Tactyks PUG Friendly", code = "!~MDT2~", pct = 101.5, pulls = { { f = 7.1, m = { 2, 8, 1, 2 }, c = { 1, 3, 1, 4, 2, 6, 2, 7, 2, 1, 2, 2, 2, 4, 2, 8, 2, 5, 2, 3 }, w = 1 }, { f = 10.5, m = { 5, 4, 3, 1, 4, 1 }, c = { 3, 4, 4, 1, 5, 7, 5, 8, 5, 6, 5, 1 }, w = 2, ne = { "Lust pull 2, 2nd boss, last boss" }, nz = { "嗜血时机：第 2 波、二号 boss、最后一个 boss" }, np = { 741.0, 285.4 } }, { f = 5.7, m = { 2, 5, 5, 2, 4, 1 }, c = { 2, 14, 2, 9, 2, 10, 2, 12, 2, 11, 4, 2, 5, 5, 5, 4 }, w = 3, ne = { "Can drag pull 1 into the room and combine with the spawned trash for a better bloodlust" }, nz = { "可以把第 1 波拖进房间，和刷出来的小怪一起打，嗜血更划算" }, np = { 646.9, 374.3 } }, { f = 0.0, m = { 6, 1 }, c = { 6, 1 }, w = 4 }, { f = 8.1, m = { 14, 1, 15, 1 }, c = { 14, 1, 15, 1 }, w = 5 }, { f = 8.6, m = { 10, 4, 9, 1 }, c = { 9, 1, 10, 1, 10, 2, 10, 4, 10, 3 }, w = 6 }, { f = 7.3, m = { 11, 1, 12, 1, 13, 1 }, c = { 11, 1, 12, 1, 13, 1 }, w = 7 }, { f = 5.7, m = { 7, 1, 8, 1 }, c = { 7, 1, 8, 1 }, w = 8 }, { f = 4.1, m = { 16, 1 }, c = { 16, 1 }, w = 9 }, { f = 6.2, m = { 26, 9, 37, 2, 17, 1 }, c = { 17, 1, 26, 6, 26, 1, 26, 2, 26, 4, 26, 8, 26, 9, 26, 5, 26, 3, 26, 7, 37, 1, 37, 2 }, w = 10 }, { f = 6.0, m = { 26, 8, 37, 2, 17, 1 }, c = { 17, 2, 26, 14, 26, 16, 26, 17, 26, 10, 26, 11, 26, 12, 26, 13, 26, 15, 37, 4, 37, 3 }, w = 11 }, { f = 0.0, m = { 18, 1, 30, 1 }, c = { 18, 1, 30, 1 }, w = 12 }, { f = 11.7, m = { 19, 2, 20, 2, 21, 2, 39, 1 }, c = { 19, 1, 19, 2, 20, 2, 20, 4, 21, 5, 21, 4, 39, 1 }, w = 13 }, { f = 5.0, m = { 21, 2, 23, 2, 19, 1, 39, 1 }, c = { 19, 3, 21, 2, 21, 6, 23, 5, 23, 6, 39, 2 }, w = 14 }, { f = 9.2, m = { 23, 2, 20, 1, 22, 1 }, c = { 20, 1, 22, 1, 23, 1, 23, 2 }, w = 15 }, { f = 0.0, m = { 27, 1, 28, 1, 29, 1, 34, 1, 35, 1, 36, 1 }, c = { 27, 1, 28, 1, 29, 1, 34, 1, 35, 1, 36, 1 }, w =