    { pos = 5, community = true, source = "wago.io", author = "Salatikue", url = "https://wago.io/-Bj3cCTUi", title = "Chill Version", views = 150, name = "Chill Version", code = "!~MDT2~", pct = 101.5, pulls = { { f = 12.8, m = { 2, 13, 1, 2, 5, 2, 4, 1 }, c = { 1, 3, 1, 4, 2, 7, 2, 1, 2, 2, 2, 4, 2, 8, 2, 5, 2, 3, 2, 6, 2, 11, 2, 9, 2, 10, 2, 14, 2, 12, 4, 1, 5, 7, 5, 8 }, w = 1 }, { f = 10.5, m = { 5, 4, 3, 1, 4, 1 }, c = { 3, 4, 4, 2, 5, 1, 5, 6, 5, 4, 5, 5 }, w = 2 }, { f = 0.0, m = { 6, 1 }, c = { 6, 1 }, w = 3 }, { f = 29.7, m = { 10, 4, 7, 1, 8, 1, 9, 1, 11, 1, 12, 1, 13, 1, 14, 1, 15, 1 }, c = { 7, 1, 8, 1, 9, 1, 10, 4, 10, 1, 10, 2, 10, 3, 11, 1, 12, 1, 13, 1, 14, 1, 15, 1 }, w = 4 }, { f = 6.2, m = { 26, 9, 37, 2, 17, 1 }, c = { 17, 1, 26, 4, 26, 1, 26, 2, 26, 8, 26, 9, 26, 5, 26, 3, 26, 6, 26, 7, 37, 1, 37, 2 }, w = 5 }, { f = 6.0, m = { 26, 8, 37, 2, 17, 1 }, c = { 17, 2, 26, 10, 26, 16, 26, 17, 26, 11, 26, 12, 26, 13, 26, 14, 26, 15, 37, 4, 37, 3 }, w = 6 }, { f = 0.0, m = { 18, 1, 30, 1 }, c = { 18, 1, 30, 1 }, w = 7 }, { f = 11.7, m = { 19, 2, 20, 2, 21, 2, 39, 1 }, c = { 19, 2, 19, 1, 20, 2, 20, 4, 21, 5, 21, 4, 39, 1 }, w = 8 }, { f = 9.1, m = { 21, 2, 23, 2, 19, 1, 22, 1, 39, 1 }, c = { 19, 3, 21, 2, 21, 6, 22, 1, 23, 6, 23, 5, 39, 2 }, w = 9 }, { f = 5.2, m = { 23, 2, 20, 1, 27, 1, 28, 1, 29, 1, 34, 1, 35, 1, 36, 1 }, c = { 20, 1, 23, 2, 23, 1, 27, 1, 28, 1, 29, 1, 34, 1, 35, 1, 36, 1 }, w = 10 }, { f = 4.9, m = { 24, 1, 33, 1 }, c = { 24, 1, 33, 1 }, w = 11 }, { f = 4.1, m = { 16, 1 }, c = { 16, 1 }, w = 12 } }, titleZh = "休闲版", codeZh = "!~MDT2~" },
  },
  ["murderrow"] = {
    { pos = 1, community = true, source = "keystone.guru", author = "alexandros_theroman", url = "https://keystone.guru/route/murder-row/XsdAG1V/skandar-tank-murder-row-season-2-10-to-15", title = "Skandar Tank - Murder Row Season 2 (+10 to +15)", views = 118725, name = "Skandar Tank - Murder Row Season 2 (+10 to +15)", code = "!~MDT2~", pct = 100.9, pulls = { { f = 10.1, m = { 1, 8, 3, 4, 2, 2, 4, 1 }, c = { 1, 1, 1, 2, 1, 3, 1, 7, 1, 8, 1, 9, 1, 5, 1, 4, 2, 3, 2, 4, 3, 1, 3, 2, 3, 3, 3, 4, 4, 1 }, w = 1, ne = { "START / FIRST BIG PULL\nLust pull. Watch Poison on tank — dispel quickly before tank busters or big hits.", "SKIP MOUNTED CAPTAIN PATROL\nAvoid the mounted Bribed Captain unless you need the count — easy accidental overpull. In low keys, just pull it in first pull and BL." }, nz = { "开局 / 第一大波\n嗜血波。注意坦克身上的毒——在坦克重击或大伤害前尽快驱散。", "跳过骑马的队长巡逻\n除非缺进度，否则避开骑马的受贿的队长——很容易多拉。低层的话直接并入第一波开嗜血。" }, np = { 724.3, 472.4, 700.8, 399.1 } }, { f = 9.2, m = { 1, 4, 2, 2, 3, 2, 4, 1, 6, 1, 39, 1 }, c = { 2, 5, 2, 6, 4, 4, 1, 16, 1, 17, 1, 18, 1, 15, 3, 8, 3, 9, 6, 5, 39, 1 }, w = 2, ne = { "FIRST SNITCH AREA\nSnitches are fixed + require OUT OF COMBAT. Finish the pack before interacting.", "SAYAAD PACK\nPRIORITY KICK: Seduction. Do not waste all kicks on Fel Missiles." }, nz = { "第一个线人区域\n线人位置固定 + 必须脱战才能交互。先把这波怪打完再交互。", "萨亚德这波\n优先打断：诱惑。别把打断全浪费在邪能飞弹上。" }, np = { 764.5, 349.1, 796.7, 377.5 } }, { f = 4.8, m = { 8, 4, 2, 4, 1, 1, 3, 1 }, c = { 1, 6, 3, 5, 8, 3, 8, 4, 8, 5, 8, 6, 2, 9, 2, 11, 2, 12, 2, 10 }, w = 3 }, { f = 4.7, m = { 1, 5, 37, 4, 3, 2, 7, 1 }, c = { 1, 11, 1, 10, 1, 12, 1, 13, 1, 14, 3, 6, 3, 7, 7, 1, 37, 1, 37, 2, 37, 3, 37, 4 }, w = 4, ne = { "LoS or grab casters from inside the room in pull 5", "Chain as soon as a couple of Sneaks are dead. Poison will reduce your health by 60% !!" }, nz = { "第 5 波卡视角，或者从房间里把法系怪拉出来", "街头扒手死掉几只就马上连拉。毒会让你的生命值降低 60% !!" }, np = { 579.2, 402.2, 502.9, 394.5 } }, { f = 0.0, m = { 21, 1, 23, 1, 38, 1 }, c = { 21, 1, 23, 1, 38, 1 }, w = 5, ne = { "KYSTIA MANAHEART\nFocus Nibbles → 20%. Save major CDs for Destabilized when Kystia takes +100% damage.", "KYSTIA MIRROR IMAGES\nInterrupt Felstorm on separate Mirror Images. Do not let multiple casts overlap." }, nz = { "凯斯媞亚·魔力之心\n集火咬咬 → 20%。大招留到“失稳”阶段，凯斯媞亚受到 +100% 伤害时再开。", "凯斯媞亚 镜像\n分别打断各个镜像的邪能风暴。别让多个读条重叠。" }, np = { 673.5, 278.1, 614.0, 279.7 } }, { f = 3.9, m = { 9, 6, 26, 5, 10, 2, 22, 1, 27, 1 }, c = { 9, 1, 9, 2, 9, 3, 9, 4, 9, 5, 9, 6, 10, 1, 10, 2, 22, 1, 26, 1, 26, 2, 26, 3, 26, 4, 26, 5, 27, 1 }, w = 6, ne = { "CANTINA EVENT\nComplete your assigned role fast → event ends at 5★. Five Star Review lasts 4 min — MOVE FAST and use buff in the next room and into boss.", "ZAEN BLADESORROW\nFire Bomb → destroy GREEN Fel-Infused Freight. Preserve the normal boxes for Murder in a Row (hide behind barrels during the laser phase).   Explode GREEN barrel is a priority!", "ZAEN — MURDER IN A ROW\nHide fully behind barrels when the red targeting lines appear. Used cover is destroyed.", "You can bring these adds into the BOSS and deal with them quickly using your BL + Bonus from Cantina :)  Or you can kill these adds first, and then start boss - up to you and your group." }, nz = { "酒馆事件\n快速完成你分配到的任务 → 5★ 时事件结束。五星好评持续 4 分钟——动作要快，在下一个房间和 boss 战里都用上这个 buff。", "赞恩·刃悲\n火焰炸弹 → 炸掉绿色的邪能灌注货物。普通箱子留给绝命凶径（激光阶段躲在桶后面）。优先引爆绿色桶！", "赞恩 — 绝命凶径\n出现红色瞄准线时完全躲到桶后面。用过的掩体会被摧毁。", "可以把这些小怪带进 boss 战，用嗜血 + 酒馆的增益快速处理掉 :) 也可以先杀掉这些小怪再开 boss——看你和队伍。" }, np = { 602.2, 85.4, 465.4, 198.1, 365.7, 175.1, 424.0, 66.3 } }, { f = 7.0, m = { 14, 2, 11, 2, 13, 1, 17, 1 }, c = { 13, 7, 14, 8, 14, 9, 17, 6, 11, 56, 11, 55 }, w = 7 }, { f = 7.1, m = { 16, 12, 14, 2, 15, 1 }, c = { 14, 10, 14, 11, 15, 1, 16, 1, 16, 2, 16, 4, 16, 5, 16, 6, 16, 7, 16, 8, 16, 9, 16, 18, 16, 19, 16, 20, 16, 21 }, w = 8, ne = { "CORRUPTED WARLOCK AREA\nPRIORITY: dispel Curse of Doom + interrupt Health Funnel. Curse dispel strongly recommended." }, nz = { "腐化的术士区域\n优先：驱散厄运诅咒 + 打断生命通道。强烈建议带驱诅咒。" }, np = { 176.2, 354.0 } }, { f = 8.0, m = { 16, 4, 13, 2, 12, 2, 17, 1 }, c = { 13, 10, 13, 12, 17, 7, 12, 13, 12, 14, 16, 10, 16, 11, 16, 13, 16, 12 }, w = 9, ne = { "You can split this pull with PUGS. Chain into Mini-Boss when you are ready. CAREFULL Shivan when it is low health it can kill you. Kill Sayad first." }, nz = { "野队可以把这波拆开拉。准备好了再连拉小 boss。小心破坏魔惩罚者，它低血量时可能秒你。先杀萨亚德。" }, np = { 202.3, 459.6 } }, { f = 6.7, m = { 16, 4, 12, 2, 18, 1 }, c = { 16, 14, 16, 15, 16, 16, 16, 17, 12, 15, 12, 16, 18, 1 }, w = 10, ne = { "SKIP MINI-BOSS! FELMASTER LUCSEI / XATHUUX APPROACH\nLucsei Blade Dance = heavy party damage. Avoid combining this miniboss with a large pull..  You can SKIP this guy here, if you hug the wall as close as you can.", "SKIP LUCSEI MINI-BOSS: Walk close to the right wall" }, nz = { "跳过小 boss！邪能主宰鲁科西 / 萨祖克斯 前路\n鲁科西的刃舞全团伤害很高。别把这个小 boss 和大波怪一起拉。这里可以跳过他，尽量贴紧墙走就行。", "跳过鲁科西小 boss：贴着右边的墙走" }, np = { 281.3, 505.6, 217.0, 511.9 } }, { f = 8.6, m = { 11, 6, 14, 2, 19, 1 }, c = { 11, 1, 11, 3, 11, 4, 11, 5, 11, 6, 11, 7, 14, 1, 14, 2, 19, 4 }, w = 11, ne = { "Boss Xathuxx: face the boss outisde. Move it slowly when it creates green polls.  Overlap the boss with Axes." }, nz = { "boss 萨祖克斯：把 boss 拉到外面打。它放绿圈时慢慢挪。让 boss 和斧子重叠。" }, np = { 318.3, 541.3 } }, { f = 7.4, m = { 11, 11, 12, 2, 14, 2, 13, 1 }, c = { 11, 8, 11, 9, 11, 10, 11, 11, 11, 12, 11, 25, 11, 26, 11, 27, 11, 28, 11, 29, 11, 30, 12, 1, 12, 3, 13, 1, 14, 3, 14, 4 }, w = 12 }, { f = 13.5, m = { 11, 12, 12, 3, 15, 1, 17, 1 }, c = { 11, 13, 11, 14, 11, 15, 11, 16, 11, 17, 11, 18, 11, 19, 11, 20, 11, 21, 11, 23, 11, 24, 11, 22, 12, 4, 12, 5, 12, 6, 15, 5, 17, 5 }, w = 13, ne = { "You do not need to pull IMPS all at once, if you are unsure. Chain slowly, deal with one wave of imps first, then chain more! :)" }, nz = { "没把握的话不用一次拉完所有小鬼。慢慢连拉，先处理一波小鬼，再连拉更多！:)" }, np = { 279.9, 257.6 } }, { f = 8.9, m = { 12, 2, 13, 2, 19, 1 }, c = { 12, 7, 12, 8, 13, 2, 13, 3, 19, 7 }, w = 14, ne = { "FINAL SECTION / BOSSES\nXathuux: move SLOW during Burning Steps. Lithiel: kill demons before Malefic Wave → use gateway." }, nz = { "最后一段 / boss\n萨祖克斯：燃烧脚步期间慢慢移动。利希尔：灾厄浪潮前杀掉恶魔 → 走传送门。" }, np = { 219.6, 81.4 } } }, titleZh = "Skandar 坦克 - 密谋小径 第二赛季（+10~+15 层）", codeZh = "!~MDT2~" },
