    { pos = 5, community = true, source = "wago.io", author = "Salatikue", url = "https://wago.io/8ULlKGO7h", title = "Keksh", views = 133, name = "Keksh", code = "!~MDT2~", pct = 100.8, pulls = { { f = 9.8, m = { 1, 3, 3, 3, 8, 2, 5, 1 }, c = { 1, 4, 1, 5, 1, 6, 3, 4, 3, 3, 3, 5, 5, 1, 8, 6, 8, 3 }, w = 1 }, { f = 9.2, m = { 1, 4, 2, 2, 3, 2, 4, 1, 6, 1, 39, 1 }, c = { 1, 16, 1, 17, 1, 18, 1, 15, 2, 6, 2, 5, 3, 9, 3, 8, 4, 4, 6, 5, 39, 1 }, w = 2 }, { f = 8.6, m = { 1, 6, 2, 4, 3, 2, 4, 1 }, c = { 1, 1, 1, 2, 1, 8, 1, 9, 1, 3, 1, 7, 2, 2, 2, 1, 2, 4, 2, 3, 3, 1, 3, 2, 4, 1 }, w = 3 }, { f = 7.4, m = { 1, 5, 2, 4, 37, 4, 3, 2, 8, 2, 7, 1 }, c = { 1, 12, 1, 13, 1, 14, 1, 10, 1, 11, 2, 10, 2, 9, 2, 12, 2, 11, 3, 7, 3, 6, 7, 1, 8, 5, 8, 4, 37, 1, 37, 2, 37, 4, 37, 3 }, w = 4 }, { f = 1.8, m = { 2, 2, 8, 2, 21, 1, 23, 1, 38, 1 }, c = { 2, 7, 2, 8, 8, 1, 8, 2, 21, 1, 23, 1, 38, 1 }, w = 5 }, { f = 3.9, m = { 9, 6, 26, 5, 10, 2, 22, 1, 27, 1 }, c = { 9, 4, 9, 6, 9, 2, 9, 3, 9, 1, 9, 5, 10, 1, 10, 2, 22, 1, 26, 3, 26, 2, 26, 1, 26, 4, 26, 5, 27, 1 }, w = 6 }, { f = 9.5, m = { 16, 4, 12, 2, 13, 2, 14, 2, 17, 1 }, c = { 12, 10, 12, 9, 13, 5, 13, 7, 14, 9, 14, 8, 16, 4, 16, 1, 16, 2, 16, 5, 17, 6 }, w = 7 }, { f = 6.5, m = { 16, 8, 14, 2, 15, 1 }, c = { 14, 10, 14, 11, 15, 1, 16, 21, 16, 18, 16, 20, 16, 19, 16, 7, 16, 8, 16, 9, 16, 6 }, w = 8 }, { f = 8.3, m = { 16, 4, 6, 2, 13, 2, 17, 1 }, c = { 6, 2, 6, 4, 13, 10, 13, 12, 16, 11, 16, 10, 16, 12, 16, 13, 17, 7 }, w = 9 }, { f = 6.7, m = { 16, 4, 12, 2, 18, 1 }, c = { 12, 15, 12, 16, 16, 16, 16, 17, 16, 14, 16, 15, 18, 1 }, w = 10 }, { f = 7.4, m = { 11, 6, 14, 4, 12, 2, 13, 1 }, c = { 11, 26, 11, 27, 11, 28, 11, 25, 11, 29, 11, 30, 12, 1, 12, 3, 13, 1, 14, 3, 14, 4, 14, 1, 14, 2 }, w = 11 }, { f = 11.7, m = { 11, 6, 12, 3, 15, 1, 17, 1 }, c = { 11, 16, 11, 14, 11, 17, 11, 13, 11, 15, 11, 18, 12, 4, 12, 5, 12, 6, 15, 5, 17, 5 }, w = 12 }, { f = 8.9, m = { 12, 2, 13, 2, 19, 1 }, c = { 12, 7, 12, 8, 13, 2, 13, 3, 19, 7 }, w = 13 } }, titleZh = "Keksh", codeZh = "!~MDT2~" },
