  ["templeofsethraliss"] = {
    { pos = 1, community = true, source = "keystone.guru", author = "alexandros_theroman", url = "https://keystone.guru/route/temple-of-sethraliss/TNN97kq/skandar-tank-temple-of-sethraliss-10-to-15", title = "Skandar Tank - Temple of Sethraliss (+10 to +15)", views = 91789, name = "Skandar Tank - Temple of Sethraliss (+10 to +15)", code = "!~MDT2~", pct = 99.9, pulls = { { f = 12.2, m = { 1, 3, 5, 3, 2, 2, 3, 1, 4, 1 }, c = { 1, 8, 1, 23, 1, 24, 2, 8, 2, 17, 3, 2, 4, 8, 5, 2, 5, 3, 5, 12 }, w = 1, ne = { "BL Here.", "Opening pull: Watch the cheeky Shrouded Fang behind you — quickly kick/CC Poisoned Cheap Shot, then LoS behind the wall to group the casters from the stairs. \nCoordinated groups can pull all the way down to the end of next set of stairs." }, nz = { "这里开嗜血。", "开局这波：小心身后偷偷摸摸的隐秘之牙 — 快速打断/控制涂毒偷袭，然后在墙后卡视角，把楼梯上的施法怪聚过来。\n配合好的队伍可以一路拉到下一段楼梯尽头。" }, np = { 750.4, 443.6, 741.6, 500.7 } }, { f = 9.5, m = { 3, 2, 5, 2, 1, 1, 2, 1, 4, 1 }, c = { 1, 21, 2, 13, 3, 6, 3, 7, 4, 3, 5, 5, 5, 10 }, w = 2, ne = { "Stonefist — \nGround Pound is heavy group damage + knock-up. Use mitigation whenever possible, especially if combined with other packs.", "Area 1: Priority defensive on  Ground Pound, use CC/stops on Arrow Barrage and kick Lightning Bolt. Large pulls become dangerous when these overlap with Krolusk bleeds." }, nz = { "Stonefist — \n震地是高额团伤 + 击飞。能开减伤就开，尤其是和别的怪一起拉的时候。", "区域 1：震地优先开减伤，箭雨用控制停掉，打断闪电箭。这些和 Krolusk 流血叠在一起时，大拉会很危险。" }, np = { 742.6, 413.2, 725.6, 386.5 } }, { f = 5.7, m = { 30, 1, 31, 1, 1, 1, 5, 1, 4, 1 }, c = { 30, 1, 31, 1, 1, 20, 5, 4, 4, 7 }, w = 3, ne = { "Adderis & Aspix: Always hit the boss without Storm Blessed. Soak Thunder and Lightning, then immediately move 20+ yards away for the follow-up. Bring funnel into the boss, 2 mobs should be enough. Tempest Winds: Three players are targeted. Place the zones", "Chain into boss when Stonefury big add is dead or below 10%" }, nz = { "阿德里斯和阿斯匹克斯：始终打没有 Storm Blessed 的那个 boss。踩电闪雷鸣，然后立刻跑开 20 码以上躲后续。顺带拉怪进 boss，2 只就够了。暴风：点 3 名玩家。放好区域", "Stonefury 大怪死了或低于 10% 时连进 boss" }, np = { 674.3, 437.4, 664.9, 409.6 } }, { f = 7.4, m = { 1, 1, 3, 1, 6, 1, 7, 1, 8, 1, 26, 1, 34, 1 }, c = { 1, 13, 3, 5, 6, 1, 7, 1, 8, 1, 26, 1, 34, 1 }, w = 4 }, { f = 6.4, m = { 1, 1, 6, 1, 7, 1, 8, 1, 34, 1 }, c = { 1, 18, 6, 2, 7, 3, 8, 3, 34, 2 }, w = 5, ne = { "Area 2: Face Sand-Sworn Riders away from the group. Interrupt Venom Bolt and use hard CC on the Faithless Subjugator channel. Coordinated group can chain or pull part of the next pack, avoid pulling 2 casters until one Adpt is killed." }, nz = { "区域 2：砂誓骑兵背对队伍。打断毒箭，无信征服者的引导用硬控。配合好的队伍可以连拉或者拉一部分下一波，在杀掉一个 Adept 之前别同时拉 2 个施法怪。" }, np = { 510.7, 372.0 } }, { f = 6.3, m = { 8, 3, 7, 2, 11, 1, 12, 1 }, c = { 7, 4, 7, 7, 8, 4, 8, 5, 8, 6, 11, 1, 12, 1 }, w = 6 }, { f = 9.5, m = { 7, 2, 1, 1, 6, 1, 11, 1, 12, 1, 34, 1, 8, 1 }, c = { 1, 19, 6, 6, 7, 5, 7, 6, 11, 6, 12, 5, 34, 3, 8, 8 }, w = 7 }, { f = 5.4, m = { 6, 1, 8, 1, 12, 1, 34, 1 }, c = { 6, 7, 8, 7, 12, 6, 34, 4 }, w = 8 }, { f = 0.0, m = { 13, 1, 20, 1, 23, 1, 32, 1, 43, 1 }, c = { 13, 1, 20, 1, 23, 1, 32, 1, 43, 1 }, w = 9, ne = { "Merektha: Save stuns for A Knot of Snakes. During Burrow, kill the Poisonous Vipers and Lightning Serpents ASAP — killing the adds ends the phase early." }, nz = { "米利克萨：晕留给缠绕的蛇群。钻地期间尽快杀剧毒蝰蛇和闪电毒蛇 — 杀掉小怪会提前结束这个阶段。" }, np = { 452.9, 215.8 } }, { f = 4.4, m = { 14, 1, 19, 1, 27, 1 }, c = { 14, 4, 19, 1, 27, 2 }, w = 10, ne = { "Storm Section: Kill the Spark Channeler to disable the maze hazards. Purge/Spellsteal Accumulate Charge from Agitated Nimbus when possible. Prio target Nimbus." }, nz = { "风暴区域：杀火花引导者关掉迷宫机关。能净化/偷取就把暴怒云气的 Accumulate Charge 处理掉。优先打云气。" }, np = { 570.2, 221.6 } }, { f = 7.1, m = { 15, 2, 16, 2, 14, 1 }, c = { 14, 1, 15, 4, 15, 1, 16, 5, 16, 10 }, w = 11 }, { f = 8.6, m = { 16, 4, 15, 2, 14, 1 }, c = { 14, 2, 15, 5, 15, 6, 16, 1, 16, 2, 16, 3, 16, 4 }, w = 12 }, { f = 0.0, m = { 25, 1, 28, 1, 33, 1 }, c = { 25, 1, 28, 1, 33, 1 }, w = 13, ne = { "Galvazzt: Dodge the initial Spire impacts, then DPS+healer soak / cover all 3 beams. Missing beams gives Galvazzt energy and makes Consume Charge increasingly dangerous." }, nz = { "加瓦兹特：先躲开尖塔落点，然后 DPS+治疗去接 / 挡住全部 3 道光束。漏接光束会给加瓦兹特充能，放电会越来越危险。" }, np = { 453.6, 148.0 } }, { f = 5.8, m = { 45, 2, 24, 1, 27, 1, 29, 1, 41, 1 }, c = { 24, 1, 27, 1, 29, 1, 41, 1, 45, 1, 45, 2 }, w = 14, ne = { "Eye Gauntlet: Assign a sturdy player for Siphon Energy. Long-CC one Temple Disruptor, interrupt/kill the other, and keep charging the Eye. Conscripts give no useful count." }, nz = { "眼睛长廊：安排一个肉的玩家接能量虹吸。一个神庙干扰者长控，另一个打断/杀掉，持续给眼睛充能。Conscript 不给有用的进度。" }, np = { 256.3, 282.3 } }, { f = 5.1, m = { 45, 2, 24, 1, 29, 1 }, c = { 24, 2, 29, 2, 45, 3, 45, 4 }, w = 15 }, { f = 6.6, m = { 42, 8, 35, 4, 17, 1 }, c = { 17, 6, 35, 1, 35, 2, 35, 4, 35, 3, 42, 6, 42, 7, 42, 8, 42, 5, 42, 9, 42, 10, 42, 12, 42, 11 }, w = 16, ne = { "Avatar of Sethraliss: Kill Essence Defilers first, control Tormentors away from the healer, assign non-healers to SOAK 3x Corrupted Lifeforce (pools) immediately!! Bloodlust (Hero) the second add wave." }, nz = { "塞塔里斯的化身：先杀精华污染者，把 Tormentor 控在远离治疗的地方，安排非治疗立刻去踩 3 个腐化生命之力（水池）！！第二波小怪开嗜血。" }, np = { 42.9, 136.7 } }, { f = 0.0, m = { 40, 4, 38, 2, 18, 1, 36, 1, 37, 1, 39, 1, 44, 1 }, c = { 18, 1, 36, 1, 37, 1, 38, 1, 38, 2, 39, 1, 40, 1, 40, 2, 40, 3, 40, 4, 44, 1 }, w = 17 } }, titleZh = "Skandar 坦克 - 塞塔里斯神庙（+10~+15 层）", codeZh = "!~MDT2~" },
    { pos = 2, community = true, source = "keystone.guru", author = "alexandros_theroman", url = "https://keystone.guru/route/temple-of-sethraliss/2kI5sUN/skandar-tank-temple-of-sethraliss-higher-keys-17-to-20", title = "Skandar Tank - Temple of Sethraliss Higher keys (+17 to +20)", views = 5801, name = "Skandar Tank - Temple of Sethraliss Higher keys (+17 to +20)", code = "!~MDT2~", pct = 98.3, pulls = { { f = 12.4, m = { 1, 3, 5, 3, 2, 2, 3, 1, 4, 1 }, c = { 1, 8, 1, 23, 1, 24, 2, 8, 2, 17, 3, 2, 4, 8, 5, 2, 5, 3, 5, 12 }, w = 1, ne = { "Opening pull: Watch the cheeky Shrouded Fang behind you — quickly kick/CC Poisoned Cheap Shot, then LoS behind the wall to group the casters from the stairs. \nCoordinated groups can pull all the way down to the end of next set of stairs.", "BL HERE" }, nz = { "开局这波：小心身后偷偷摸摸的隐秘之牙 — 快速打断/控制涂毒偷袭，然后在墙后卡视角，把楼梯上的施法怪聚过来。\n配合好的队伍可以一路拉到下一段楼梯尽头。", "这里开嗜血" }, np = { 756.6, 492.2, 752.7, 474.6 } }, { f = 9.6, m = { 3, 2, 5, 2, 1, 1, 2, 1, 4, 1 }, c = { 1, 21, 2, 13, 3, 6, 3, 7, 4, 3, 5, 5, 5, 10 }, w = 2, ne = { "Area 1: Priority stops are Arrow Barrage and kick Lightning Bolt. Large pulls become dangerous when these overlap with Krolusk bleeds. Ground Pound use defensive.", "Adderis & Aspix: Always hit the boss without Storm Blessed. Soak Thunder and Lightning, then immediately move 20+ yards away for the follow-up. Bring funnel into the boss, 2 mobs should be enough. Tempest Winds: Three players are targeted. Place the zones" }, nz = { "区域 1：优先控制停掉箭雨，打断闪电箭。这些和 Krolusk 流血叠在一起时，大拉会很危险。震地开减伤。", "阿德里斯和阿斯匹克斯：始终打没有 Storm Blessed 的那个 boss。踩电闪雷鸣，然后立刻跑开 20 码以上躲后续。顺带拉怪进 boss，2 只就够了。暴风：点 3 名玩家。放好区域" }, np = { 735.0, 384.8, 703.0, 409.1 } }, { f = 0.0, m = { 30, 1, 31, 1 }, c = { 30, 1, 31, 1 }, w = 3 }, { f = 12.4, m = { 2, 2, 1, 1, 3, 1, 6, 1, 7, 1, 8, 1, 10, 1, 26, 1, 9, 1, 34, 1 }, c = { 1, 13, 2, 10, 2, 9, 3, 5, 6, 1, 7, 1, 8, 1, 10, 1, 26, 1, 9, 1, 34, 1 }, w = 4 }, { f = 8.6, m = { 1, 1, 6, 1, 7, 1, 8, 1, 34, 1, 11, 1, 12, 1 }, c = { 1, 18, 6, 2, 7, 3, 8, 3, 34, 2, 11, 1, 12, 1 }, w = 5, ne = { "Area 2: Face Sand-Sworn Riders away from the group. Interrupt Venom Bolt and use hard CC on the Faithless Subjugator channel. Coordinated group can chain or pull part of the next pack, avoid pulling 2 casters until one Adpt is killed." }, nz = { "区域 2：砂誓骑兵背对队伍。打断毒箭，无信征服者的引导用硬控。配合好的队伍可以连拉或者拉一部分下一波，在杀掉一个 Adept 之前别同时拉 2 个施法怪。" }, np = { 491.9, 299.9 } }, { f = 10.1, m = { 8, 3, 11, 1, 7, 1, 1, 1, 12, 1, 34, 1, 6, 1 }, c = { 11, 6, 7, 4, 8, 8, 8, 4, 8, 5, 1, 19, 12, 5, 34, 3, 6, 6 }, w = 6 }, { f = 9.3, m = { 7, 3, 8, 2, 6, 1, 12, 1, 34, 1 }, c = { 6, 7, 7, 7, 7, 6, 7, 5, 8, 7, 8, 6, 12, 6, 34, 4 }, w = 7, ne = { "Merektha: Save stuns for A Knot of Snakes. During Burrow, kill the Poisonous Vipers and Lightning Serpents ASAP — killing the adds ends the phase early." }, nz = { "米利克萨：晕留给缠绕的蛇群。钻地期间尽快杀剧毒蝰蛇和闪电毒蛇 — 杀掉小怪会提前结束这个阶段。" }, np = { 467.9, 224.2 } }, { f = 0.0, m = { 20, 1, 13, 1, 32, 1, 23, 1, 43, 1 }, c = { 20, 1, 13, 1, 32, 1, 23, 1, 43, 1 }, w = 8 }, { f = 11.7, m = { 14, 2, 15, 2, 16, 2, 19, 1, 27, 1 }, c = { 14, 1, 14, 4, 15, 1, 15, 4, 16, 5, 16, 10, 19, 1, 27, 2 }, w = 9, ne = { "Chain here when Channeler dies.", "Storm Section: Kill the Spark Channeler to disable the maze hazards. Purge/Spellsteal Accumulate Charge from Agitated Nimbus when possible. Prio target Nimbus." }, nz = { "引导者死了就在这里连拉。", "风暴区域：杀火花引导者关掉迷宫机关。能净化/偷取就把暴怒云气的 Accumulate Charge 处理掉。优先打云气。" }, np = { 572.2, 157.8, 570.4, 214.3 } }, { f = 8.7, m = { 16, 4, 15, 2, 14, 1 }, c = { 14, 2, 16, 1, 16, 2, 16, 3, 16, 4, 15, 5, 15, 6 }, w = 10, ne = { "Galvazzt: Dodge the initial Spire impacts, then DPS+healer soak / cover all 3 beams. Missing beams gives Galvazzt energy and makes Consume Charge increasingly dangerous." }, nz = { "加瓦兹特：先躲开尖塔落点，然后 DPS+治疗去接 / 挡住全部 3 道光束。漏接光束会给加瓦兹特充能，放电会越来越危险。" }, np = { 493.6, 138.0 } }, { f = 0.0, m = { 25, 1, 33, 1, 28, 1 }, c = { 25, 1, 33, 1, 28, 1 }, w = 11 }, { f = 10.4, m = { 45, 4, 24, 2, 29, 2 }, c = { 24, 1, 24, 2, 45, 1, 45, 2, 45, 4, 45, 3, 29, 1, 29, 2 }, w = 12, ne = { "Eye Gauntlet: Assign a sturdy player for Siphon Energy. Long-CC one Temple Disruptor, interrupt/kill the other, and keep charging the Eye. Conscripts give no useful count." }, nz = { "眼睛长廊：安排一个肉的玩家接能量虹吸。一个神庙干扰者长控，另一个打断/杀掉，持续给眼睛充能。Conscript 不给有用的进度。" }, np = { 263.1, 284.9 } }, { f = 6.7, m = { 42, 8, 35, 4, 17, 1 }, c = { 42, 6, 42, 7, 42, 8, 42, 5, 42, 9, 42, 10, 42, 12, 42, 11, 17, 6, 35, 1, 35, 2, 35, 4, 35, 3 }, w = 13, ne = { "Avatar of Sethraliss: Kill Essence Defilers first, control Tormentors away from the healer, assign non-healers to SOAK 3x Corrupted Lifeforce (pools) immediately!! Bloodlust (Hero) the second add wave." }, nz = { "塞塔里斯的化身：先杀精华污染者，把 Tormentor 控在远离治疗的地方，安排非治疗立刻去踩 3 个腐化生命之力（水池）！！第二波小怪开嗜血。" }, np = { 42.9, 136.7 } }, { f = 0.0, m = { 40, 4, 38, 2, 36, 1, 37, 1, 18, 1, 44, 1, 39, 1 }, c = { 36, 1, 37, 1, 38, 1, 38, 2, 18, 1, 40, 1, 40, 2, 40, 3, 40, 4, 44, 1, 39, 1 }, w = 14 } }, titleZh = "Skandar 坦克 - 塞塔里斯神庙 高层（+17~+20 层）", codeZh = "!~MDT2~" },
