, ne = { "% в роуте правильный, ошибка в MDT, ничего добирать не нужно" }, nz = { "路线里的 % 是对的，是 MDT 的错误，不用补进度" }, np = { 329.0, 247.7 } }, { f = 6.7, m = { 42, 8, 35, 4, 17, 1 }, c = { 17, 6, 35, 1, 35, 2, 35, 4, 35, 3, 42, 11, 42, 10, 42, 12, 42, 9, 42, 8, 42, 6, 42, 7, 42, 5 }, w = 16 } }, titleZh = "休闲版", codeZh = "!~MDT2~" },
