  ["theblindingvale"] = {
    { pos = 1, community = true, source = "keystone.guru", author = "alexandros_theroman", url = "https://keystone.guru/route/the-blinding-vale/oXwdXdU/skandar-tank-blinding-vale-season-2-10-to-15", title = "Skandar Tank - Blinding Vale Season 2 (+10 to +15)", views = 157498, name = "Skandar Tank - Blinding Vale Season 2 (+10 to +15)", code = "!~MDT2~", pct = 101.6, pulls = { { f = 9.8, m = { 2, 8, 1, 3, 3, 2, 6, 1, 4, 1 }, c = { 1, 11, 1, 12, 1, 13, 2, 27, 2, 28, 2, 29, 2, 30, 2, 31, 2, 32, 2, 33, 2, 34, 6, 4, 4, 2, 3, 3, 3, 4 }, w = 1, ne = { "MDT / Keystone are not updated - count is actually incorrect, but you will be fine when you play this :)", "Opening Route — Go Left\nCurrent layout is cleaner on the left. Easier pull boundaries and the first Belcher no longer patrols. BL HERE FIRST PULL!", "Virid Grovekeeper\nUproot = party damage + knockback. Avoid Earthrupture ground effects and don’t get knocked into nearby packs." }, nz = { "MDT / Keystone 没更新——进度其实不对，但实际打的时候没问题 :)", "开局路线 — 走左边\n当前布局左边更干净，拉怪边界更好控，第一个喷射者也不再巡逻了。第一波开嗜血！", "翠绿林地守护者\n拔根而起 = 全队伤害 + 击退。躲开 Earthrupture 地面效果，别被击退进旁边的怪堆。" }, np = { 70.1, 298.5, 44.2, 242.5, 75.3, 201.0 } }, { f = 10.0, m = { 2, 5, 1, 3, 3, 2, 5, 1, 6, 1 }, c = { 1, 18, 1, 19, 1, 24, 2, 50, 2, 51, 2, 82, 2, 83, 2, 84, 3, 9, 3, 10, 5, 9, 6, 7 }, w = 2, ne = { "Spellsowers — Priority Kick\nKick Light Volley first. At low HP, Spellsowers may run to dormant Lashers — stun, knock or kill them before they wake extra mobs.", "Sporeblight Belcher\nSprouting Flora = heavy group damage. Avoid combining it with too many bleeds/volleys unless healer CDs are ready." }, nz = { "播法者 — 优先打断\n优先打断 Light Volley。残血时播法者可能会跑向休眠的鞭笞者——在它们叫醒更多怪之前晕住、击退或杀掉。", "孢荒喷射者\nSprouting Flora = 全队大伤害。除非治疗大招好了，否则别和太多流血/乱射叠在一起。" }, np = { 131.3, 179.4, 108.4, 114.7 } }, { f = 9.9, m = { 2, 11, 3, 2, 6, 2, 1, 1, 5, 1 }, c = { 1, 17, 2, 44, 2, 45, 2, 46, 2, 47, 2, 48, 2, 49, 2, 52, 2, 53, 2, 54, 2, 55, 2, 56, 3, 5, 3, 6, 5, 7, 6, 9, 6, 15 }, w = 3 }, { f = 6.9, m = { 2, 7, 1, 2, 4, 1, 6, 1 }, c = { 1, 15, 1, 16, 2, 37, 2, 38, 2, 39, 2, 40, 2, 41, 2, 42, 2, 43, 4, 3, 6, 5 }, w = 4, ne = { "Bring 2 mobs from pull 4 into Boss for funnel and continuity of damage ramp." }, nz = { "把第 4 波的 2 个怪带进 boss，打顺劈并保持伤害爬升不断档。" }, np = { 342.6, 77.0 } }, { f = 1.3, m = { 2, 2, 1, 1, 14, 1, 15, 1, 13, 1 }, c = { 1, 14, 2, 35, 2, 36, 14, 1, 15, 1, 13, 1 }, w = 5, ne = { "Lightblossom Trinity — Beam Soaks\nKeep all 3 bosses stacked. When Lightblossom Beam starts, assign 1 player per blossom — tank/healer/DPS works well.", "Trinity — Movement\nKick Light Bolt. Avoid Lightsower Dash lines and move away from Fan of Thorns. Tank defensives for Bedrock Slam." }, nz = { "Lightblossom Trinity — 吃光束\n三个 boss 集合在一起。Lightblossom Beam 开始时，每朵花分配 1 个人——坦克/治疗/DPS 各一个就行。", "三人组 — 走位\n打断光芒箭。躲开播光急奔的线，远离荆棘之扇。坦克给 Bedrock Slam 开减伤。" }, np = { 412.1, 90.5, 386.8, 78.9 } }, { f = 11.6, m = { 2, 5, 3, 2, 1, 1, 4, 1, 5, 1, 7, 1, 8, 1 }, c = { 1, 25, 2, 90, 2, 91, 2, 92, 2, 93, 2, 94, 3, 11, 3, 12, 4, 5, 5, 10, 7, 16, 8, 9 }, w = 6, ne = { "You can pull the whole bridge here and BL / HERO :)", "Bridge Pull\nSafer as 2 pulls while learning. Kick Disorienting Screech and dodge the Thorny Saptor’s targeted frontal." }, nz = { "这里可以把整座桥拉了，开嗜血 :)", "桥上拉怪\n还在熟悉的话分 2 波拉更安全。打断迷乱尖叫，躲开多刺的迅叶龙的点名正面。" }, np = { 415.8, 185.8, 405.8, 158.9 } }, { f = 0.0, m = { 18, 1 }, c = { 18, 1 }, w = 7, ne = { "Ikuzz — Stack the Roots\nStack close before Verdant Stomp/root spawns, but don’t overlap circles. Cleave Bloodthorn Roots together or use root-breaking utility." }, nz = { "伊库兹 — 集合踩根\n青翠践踏/根须出现前靠近集合，但圈别重叠。把血棘之根一起顺劈掉，或者用破根的技能。" }, np = { 393.5, 359.1 } }, { f = 7.3, m = { 9, 5, 8, 2, 7, 1, 10, 1, 12, 1 }, c = { 7, 17, 8, 10, 8, 12, 9, 18, 9, 19, 9, 20, 9, 21, 9, 22, 10, 9, 12, 4 }, w = 8, ne = { "Do not be greedy! Pull the whole bridge if you want, BUT split the pulls on the next platform before boss. Do not copy Rank 1 players here, you can split into 3 pulls." }, nz = { "别贪！想拉整座桥可以，但 boss 前的下一个平台要分开拉。这里别学 Rank 1 玩家，可以分 3 波拉。" }, np = { 659.4, 213.9 } }, { f = 6.6, m = { 9, 5, 10, 2, 8, 1, 12, 1 }, c = { 8, 11, 10, 10, 10, 11, 12, 5, 9, 30, 9, 31, 9, 32, 9, 39, 9, 33 }, w = 9, ne = { "Kick Lightfeathers here or wipe! :D  Be careful frontal, fight near the platform to give you more space.", "Kill mobs by the edges to drop pools NOT in the middle." }, nz = { "这里光羽瓣翼鸟必须打断，不然灭团！:D  小心正面，靠平台边打，给自己留更多空间。", "在边缘杀怪，水池别掉在中间。" }, np = { 720.4, 217.0, 776.8, 286.4 } }, { f = 5.0, m = { 9, 5, 8, 1, 16, 1, 20, 1, 21, 1, 5, 1 }, c = { 8, 13, 16, 1, 20, 1, 21, 1, 9, 38, 9, 34, 9, 36, 9, 37, 9, 35, 5, 11 }, w = 10, ne = { "Ruia — Dangerous Final Phase\nAim Lightfire away, spread Pulverizing Strikes and top Grievous Thrash bleeds. Save BL + major CDs for 40%.  Do NOT stack the Light / tornado mechanics!" }, nz = { "鲁伊亚 — 危险的最后阶段\n光明之火朝外放，粉碎打击散开，凶残痛击的流血要刷满。嗜血 + 大招留到 40%。光 / 龙卷风机制千万别叠在一起！" }, np = { 846.1, 236.7 } }, { f = 14.6, m = { 2, 7, 7, 3, 1, 2, 23, 1 }, c = { 1, 8, 1, 9, 2, 8, 2, 9, 2, 10, 2, 11, 2, 12, 2, 13, 2, 14, 7, 2, 7, 3, 7, 4, 23, 1 }, w = 11, ne = { "Potatoad + Final Trash. Go down / left here.\nTank the Matriarch with your back toward cleared ground for Tongue Toss. Near the final trigger, be ready to grip/silence/kick spread casters immediately.", "DPS: each of you mark one of these Lightfeathers and kick the Disorienting Screech spell." }, nz = { "薯身蟾主母 + 最后的小怪。这里往下 / 往左走。\n坦克背对已清空的地面拉主母，应对吐舌攻击。靠近最后触发点时，准备好立刻拉/沉默/打断散开的施法怪。", "DPS：每人标记一只光羽瓣翼鸟，打断迷乱尖叫。" }, np = { 515.2, 230.7, 492.8, 310.5 } }, { f = 16.9, m = { 1, 6, 2, 6, 6, 2, 3, 1, 5, 1, 11, 1 }, c = { 3, 2, 5, 3, 11, 3, 1, 2, 1, 3, 1, 4, 1, 5, 1, 6, 1, 7, 2, 2, 2, 3, 2, 4, 2, 5, 2, 7, 2, 6, 6, 2, 6, 3 }, w = 12, ne = { "You can skip going through the large pack to the right and the big mob to the left. You can try using Mage invisibility or shroud, but big mob will still see you - just skip and stay away from them, Go into boss from the left hand side.  Carefull sleepy hydra and other mobs!", "Ikuzz — Bloodthirsty Gaze\nFixated player should kite Ikuzz through existing root clusters so the boss destroys them. Keep the arena clean for later cycles." }, nz = { "右边的大波怪和左边的大怪可以跳过。可以用法师隐形或暗影斗篷，但大怪还是会看到你——直接跳过、离它们远点，从左侧进 boss。小心睡着的长得过大的多头花和其他怪！", "伊库兹 — Bloodthirsty Gaze\n被盯的人带着伊库兹穿过已有的根堆，让 boss 把它们踩掉。保持场地干净，方便后面的轮次。" }, np = { 332.0, 361.9, 404.7, 334.3 } }, { f = 0.0, m = { 17, 1, 22, 1, 26, 1 }, c = { 17, 1, 22, 1, 26, 1 }, w = 13, ne = { "Ziekket — Lasher Setup\nGroup Lashers beside the boss and cleave them to Dormant. Soak Essence orbs, then line up Concentrated Lightbeam through every dormant Lasher before moving to clean space." }, nz = { "兹欧凯特 — 鞭笞者处理\n把鞭笞者拉到 boss 旁边，顺劈打到休眠。吃掉 Essence 球，然后让凝聚光线穿过每个休眠的鞭笞者，再换到干净的位置。" }, np = { 229.2, 303.8 } } }, titleZh = "Skandar 坦克 - 夺目谷 第二赛季（+10~+15 层）", codeZh = "!~MDT2~" },
    { pos = 2, community = true, source = "keystone.guru", author = "alexandros_theroman", url = "https://keystone.guru/route/the-blinding-vale/5fTirH0/skandar-tank-blinding-vale-season-2-higher-keys-17-to-20", title = "Skandar Tank - Blinding Vale Season 2 (Higher Keys +17 to +20)", views = 13627, name = "Skandar Tank - Blinding Vale Season 2 (Higher Keys +17 to +2", code = "!~MDT2~", pct = 101.3, pulls = { { f = 13.1, m = { 2, 8, 3, 4, 1, 2, 4, 1, 5, 1 }, c = { 1, 13, 1, 24, 2, 82, 2, 83, 2, 84, 2, 85, 2, 86, 2, 87, 2, 88, 2, 89, 3, 3, 3, 4, 3, 9, 3, 10, 4, 2, 5, 9 }, w = 1, ne = { "SKIP!  You can mass invis or shroud this first pack", "Spellsowers — Priority Kick\nKick Light Volley first. At low HP, Spellsowers may run to dormant Lashers — stun, knock or kill them before they wake extra mobs.", "Virid Grovekeeper\nUproot = party damage + knockback. Avoid Earthrupture ground effects and don’t get knocked into nearby packs.", "Opening Route — Go Left\nCurrent layout is cleaner on the left. Easier pull boundaries and the first Belcher no longer patrols. BL HERE FIRST PULL!" }, nz = { "跳过！第一波可以群体隐形或暗影斗篷过去", "播法者 — 优先打断\n优先打断 Light Volley。残血时播法者可能会跑向休眠的鞭笞者——在它们叫醒更多怪之前晕住、击退或杀掉。", "翠绿林地守护者\n拔根而起 = 全队伤害 + 击退。躲开 Earthrupture 地面效果，别被击退进旁边的怪堆。", "开局路线 — 走左边\n当前布局左边更干净，拉怪边界更好控，第一个喷射者也不再巡逻了。第一波开嗜血！" }, np = { 70.1, 298.5, 131.3, 179.4, 75.3, 201.0, 85.5, 135.4 } }, { f = 7.9, m = { 1, 2, 2, 2, 6, 2, 5, 1 }, c = { 1, 18, 1, 19, 2, 50, 2, 51, 5, 7, 6, 7, 6, 15 }, w = 2, ne = { "Sporeblight Belcher\nSprouting Flora = heavy group damage. Avoid combining it with too many bleeds/volleys unless healer CDs are ready.", "Bring 2 mobs from pull 4 into Boss for funnel and continuity of damage ramp." }, nz = { "孢荒喷射者\nSprouting Flora = 全队大伤害。除非治疗大招好了，否则别和太多流血/乱射叠在一起。", "把第 4 波的 2 个怪带进 boss，打顺劈并保持伤害爬升不断档。" }, np = { 108.4, 114.7, 162.1, 93.0 } }, { f = 10.6, m = { 2, 14, 1, 2, 6, 2, 3, 2, 4, 1 }, c = { 1, 16, 1, 17, 2, 41, 2, 42, 2, 43, 2, 44, 2, 45, 2, 46, 2, 47, 2, 48, 2, 49, 2, 52, 2, 53, 2, 54, 2, 55, 2, 56, 6, 5, 6, 9, 3, 5, 3, 6, 4, 3 }, w = 3, ne = { "Trinity — Movement\nKick Light Bolt. Avoid Lightsower Dash lines and move away from Fan of Thorns. Tank defensives for Bedrock Slam." }, nz = { "三人组 — 走位\n打断光芒箭。躲开播光急奔的线，远离荆棘之扇。坦克给 Bedrock Slam 开减伤。" }, np = { 295.7, 63.0 } }, { f = 2.9, m = { 2, 6, 1, 2, 13, 1, 15, 1, 14, 1 }, c = { 13, 1, 15, 1, 14, 1, 1, 14, 1, 15, 2, 35, 2, 36, 2, 37, 2, 38, 2, 39, 2, 40 }, w = 4, ne = { "Lightblossom Trinity — Beam Soaks\nKeep all 3 bosses stacked. When Lightblossom Beam starts, assign 1 player per blossom — tank/healer/DPS works well." }, nz = { "Lightblossom Trinity — 吃光束\n三个 boss 集合在一起。Lightblossom Beam 开始时，每朵花分配 1 个人——坦克/治疗/DPS 各一个就行。" }, np = { 376.3, 67.7 } }, { f = 11.7, m = { 2, 5, 3, 2, 1, 1, 4, 1, 5, 1, 7, 1, 8, 1 }, c = { 1, 25, 2, 90, 2, 91, 2, 92, 2, 93, 2, 94, 3, 11, 3, 12, 4, 5, 5, 10, 7, 16, 8, 9 }, w = 5, ne = { "Bridge Pull\nSafer as 2 pulls while learning. Kick Disorienting Screech and dodge the Thorny Saptor’s targeted frontal.", "You can pull the whole bridge here and BL / HERO :)" }, nz = { "桥上拉怪\n还在熟悉的话分 2 波拉更安全。打断迷乱尖叫，躲开多刺的迅叶龙的点名正面。", "这里可以把整座桥拉了，开嗜血 :)" }, np = { 405.8, 158.9, 412.7, 164.6 } }, { f = 0.0, m = { 18, 1 }, c = { 18, 1 }, w = 6, ne = { "Ikuzz — Stack the Roots\nStack close before Verdant Stomp/root spawns, but don’t overlap circles. Cleave Bloodthorn Roots together or use root-breaking utility." }, nz = { "伊库兹 — 集合踩根\n青翠践踏/根须出现前靠近集合，但圈别重叠。把血棘之根一起顺劈掉，或者用破根的技能。" }, np = { 405.9, 346.8 } }, { f = 7.3, m = { 9, 5, 8, 2, 7, 1, 10, 1, 12, 1 }, c = { 7, 17, 8, 10, 8, 12, 10, 9, 12, 4, 9, 18, 9, 19, 9, 20, 9, 21, 9, 22 }, w = 7, ne = { "Do not be greedy! Pull the whole bridge if you want, BUT split the pulls on the next platform before boss. Do not copy Rank 1 players here, you can split into 3 pulls." }, nz = { "别贪！想拉整座桥可以，但 boss 前的下一个平台要分开拉。这里别学 Rank 1 玩家，可以分 3 波拉。" }, np = { 695.1, 212.5 } }, { f = 5.6, m = { 9, 5, 8, 1, 10, 1, 12, 1 }, c = { 8, 11, 9, 30, 9, 31, 9, 32, 9, 33, 9, 39, 10, 10, 12, 5 }, w = 8, ne = { "chain these pulls. Kill mobs by the edges to drop pools NOT in the middle." }, nz = { "这几波连拉。在边缘杀怪，水池别掉在中间。" }, np = { 776.8, 286.4 } }, { f = 5.3, m = { 9, 5, 10, 1, 5, 1 }, c = { 10, 11, 5, 11, 9, 34, 9, 35, 9, 36, 9, 38, 9, 37 }, w = 9, ne = { "Kick Lightfeathers here or wipe! :D  Be careful frontal, fight near the platform to give you more space." }, nz = { "这里光羽瓣翼鸟必须打断，不然灭团！:D  小心正面，靠平台边打，给自己留更多空间。" }, np = { 720.4, 217.0 } }, { f = 0.7, m = { 16, 1, 20, 1, 21, 1, 8, 1 }, c = { 16, 1, 20, 1, 21, 1, 8, 13 }, w = 10 }, { f = 14.7, m = { 2, 7, 7, 3, 1, 2, 23, 1 }, c = { 1, 8, 1, 9, 2, 8, 2, 9, 2, 10, 2, 11, 2, 12, 2, 13, 2, 14, 23, 1, 7, 2, 7, 3, 7, 4 }, w = 11, ne = { "DPS: each of you mark one of these Lightfeathers and kick the Disorienting Screech spell.", "Chain Belcher as soon as possible from pull 11", "Potatoad + Final Trash. Go down / left here.\nTank the Matriarch with your back toward cleared ground for Tongue Toss. Near the final trigger, be ready to grip/silence/kick spread casters immediately." }, nz = { "DPS：每人标记一只光羽瓣翼鸟，打断迷乱尖叫。", "第 11 波尽快连拉喷射者", "薯身蟾主母 + 最后的小怪。这里往下 / 往左走。\n坦克背对已清空的地面拉主母，应对吐舌攻击。靠近最后触发点时，准备好立刻拉/沉默/打断散开的施法怪。" }, np = { 492.8, 310.5, 459.0, 286.3, 512.1, 228.6 } }, { f = 11.2, m = { 3, 1, 5, 1, 11, 1, 12, 1 }, c = { 3, 2, 5, 3, 11, 3, 12, 2 }, w = 12, ne = { "Ikuzz — Bloodthirsty Gaze\nFixated player should kite Ikuzz through existing root clusters so the boss destroys them. Keep the arena clean for later cycles." }, nz = { "伊库兹 — Bloodthirsty Gaze\n被盯的人带着伊库兹穿过已有的根堆，让 boss 把它们踩掉。保持场地干净，方便后面的轮次。" }, np = { 404.7, 334.3 } }, { f = 8.9, m = { 1, 6, 2, 6, 6, 2 }, c = { 1, 2, 1, 3, 1, 4, 1, 5, 1, 7, 1, 6, 2, 2, 2, 3, 2, 4, 2, 5, 2, 6, 2, 7, 6, 2, 6, 3 }, w = 13, ne = { "You can skip everything here by hugging left, entering the bamboo forest OR going through the large pack to the right and the big mob to the left. You can try using Mage invisibility or shroud, but some mobs will still see you - just skip and stay away from them, Go into boss from the left hand side.  Carefull sleepy hydra and other mobs!" }, nz = { "贴左边走进竹林就能跳过这里所有怪，或者从右边大波怪和左边大怪中间穿过去。可以用法师隐形或暗影斗篷，但有些怪还是会看到你——直接跳过、离它们远点，从左侧进 boss。小心睡着的长得过大的多头花和其他怪！" }, np = { 354.7, 358.3 } }, { f = 0.0, m = { 22, 1, 17, 1, 26, 1 }, c = { 22, 1, 17, 1, 26, 1 }, w = 14, ne = { "Ziekket — Lasher Setup\nGroup Lashers beside the boss and cleave them to Dormant. Soak Essence orbs, then line up Concentrated Lightbeam through every dormant Lasher before moving to clean space." }, nz = { "兹欧凯特 — 鞭笞者处理\n把鞭笞者拉到 boss 旁边，顺劈打到休眠。吃掉 Essence 球，然后让凝聚光线穿过每个休眠的鞭笞者，再换到干净的位置。" }, np = { 234.7, 266.7 } } }, titleZh = "Skandar 坦克 - 夺目谷 第二赛季（高层 +17~+20 层）", codeZh = "!~MDT2~" },
    { pos = 3, community = true, source = "keystone.guru", author = "Supers", url = "https://keystone.guru/route/the-blinding-vale/3x3bDP3/supers-12-20", title = "Supers 12-20", views = 5458, name = "Supers 12-20", code = "!~MDT2~", pct = 101.5, pulls = { { f = 14.7, m = { 2, 15, 1, 5, 3, 3, 6, 2, 4, 1 }, c = { 1, 11, 1, 13, 1, 22, 1, 23, 1, 24, 2, 27, 2, 28, 2, 29, 2, 73, 2, 74, 2, 75, 2, 76, 2, 77, 2, 78, 2, 79, 2, 80, 2, 81, 2, 82, 2, 83, 2, 84, 3, 3, 3, 4, 3, 8, 4, 2, 6, 4, 6, 11 }, w = 1 }, { f = 8.6, m = { 3, 2, 1, 2, 2, 2, 5, 1, 6, 1 }, c = { 3, 9, 3, 10, 5, 9, 1, 18, 1, 19, 2, 50, 2, 51, 6, 7 }, w = 2 }, { f = 8.0, m = { 2, 5, 3, 2, 6, 2, 5, 1 }, c = { 2, 52, 2, 53, 2, 54, 2, 55, 2, 56, 3, 5, 3, 6, 5, 7, 6, 9, 6, 15 }, w = 3 }, { f = 10.1, m = { 2, 15, 1, 4, 6, 1, 4, 1 }, c = { 1, 17, 1, 16, 1, 15, 1, 14, 2, 44, 2, 45, 2, 46, 2, 47, 2, 48, 2, 49, 2, 41, 2, 42, 2, 43, 2, 37, 2, 38, 2, 39, 2, 40, 2, 36, 2, 35, 6, 5, 4, 3 }, w = 4 }, { f = 0.0, m = { 13, 1, 14, 1, 15, 1 }, c = { 13, 1, 14, 1, 15, 1 }, w = 5 }, { f = 11.6, m = { 2, 5, 3, 2, 1, 1, 4, 1, 5, 1, 7, 1, 8, 1 }, c = { 1, 25, 2, 90, 2, 91, 2, 92, 2, 93, 2, 94, 3, 11, 3, 12, 4, 5, 5, 10, 7, 16, 8, 9 }, w = 6 }, { f = 0.0, m = { 18, 1 }, c = { 18, 1 }, w = 7 }, { f = 6.6, m = { 9, 5, 7, 1, 8, 1, 10, 1, 12, 1 }, c = { 7, 17, 8, 10, 9, 18, 9, 19, 9, 20, 9, 21, 9, 22, 10, 9, 12, 4 }, w = 8 }, { f = 12.4, m = { 9, 10, 8, 3, 10, 2, 5, 1, 12, 1 }, c = { 5, 11, 10, 11, 10, 10, 12, 5, 8, 11, 8, 12, 8, 13, 9, 31, 9, 32, 9, 33, 9, 39, 9, 30, 9, 34, 9, 35, 9, 36, 9, 38, 9, 37 }, w = 9 }, { f = 0.0, m = { 16, 1, 20, 1, 21, 1 }, c = { 16, 1, 20, 1, 21, 1 }, w = 10 }, { f = 11.6, m = { 2, 7, 1, 2, 23, 1 }, c = { 1, 8, 1, 9, 2, 8, 2, 9, 2, 10, 2, 11, 2, 12, 2, 13, 2, 14, 23, 1 }, w = 11 }, { f = 9.8, m = { 7, 3, 5, 1, 12, 1 }, c = { 5, 3, 7, 2, 7, 3, 7, 4, 12, 2 }, w = 12 }, { f = 6.6, m = { 3, 2, 6, 2, 4, 1 }, c = { 3, 15, 3, 16, 6, 13, 6, 14, 4, 7 }, w = 13 }, { f = 0.0, m = { 17, 1 }, c = { 17, 1 }, w = 14 } }, titleZh = "12-20 层", codeZh = "!~MDT2~" },
    { pos = 4, community = true, source = "wago.io", author = "Tactyks", url = "https://wago.io/HLI3Wq7sA", title = "Tactyks PUG Friendly BLINDING VALE M+ Route | Midnight Season 2", views = 715, name = "Tactyks PUG Friendly", code = "!~MDT2~", pct = 98.3, pulls = { { f = 8.8, m = { 9, 3, 8, 2, 10, 2, 7, 1, 11, 1 }, c = { 7, 8, 8, 2, 8, 3, 9, 2, 9, 1, 9, 3, 10, 2, 10, 3, 11, 5 }, w = 1, ne = { "Lust pull 1, 2nd boss, Last boss" }, nz = { "嗜血：第 1 波、老二、尾王" }, np = { 45.4, 298.9 } }, { f = 8.0, m = { 9, 5, 8, 2, 5, 1, 7, 1, 10, 1 }, c = { 5, 4, 7, 9, 8, 1, 8, 4, 9, 11, 9, 10, 9, 6, 9, 4, 9, 5, 10, 4 }, w = 2 }, { f = 7.3, m = { 8, 2, 7, 1, 10, 1, 11, 1 }, c = { 7, 14, 8, 5, 8, 6, 10, 5, 11, 6 }, w = 3 }, { f = 5.8, m = { 10, 2, 11, 1 }, c = { 10, 7, 10, 8, 11, 7 }, w = 4 }, { f = 5.5, m = { 5, 1, 7, 1, 8, 1 }, c = { 5, 6, 7, 15, 8, 8 }, w = 5 }, { f = 0.0, m = { 18, 1 }, c = { 18, 1 }, w = 6 }, { f = 12.0, m = { 2, 5, 3, 2, 1, 1, 4, 1, 5, 1, 7, 1, 8, 1 }, c = { 1, 25, 2, 93, 2, 91, 2, 94, 2, 90, 2, 92, 3, 12, 3, 11, 4, 5, 5, 10, 7, 16, 8, 9 }, w = 7 }, { f = 0.0, m = { 13, 1, 14, 1, 15, 1 }, c = { 13, 1, 14, 1, 15, 1 }, w = 8 }, { f = 6.8, m = { 9, 5, 7, 1, 8, 1, 10, 1, 12, 1 }, c = { 7, 17, 8, 10, 9, 19, 9, 18, 9, 20, 9, 21, 9, 22, 10, 9, 12, 4 }, w = 9 }, { f = 6.8, m = { 8, 2, 10, 2, 12, 1 }, c = { 8, 12, 8, 11, 10, 10, 10, 11, 12, 5 }, w = 10 }, { f = 0.7, m = { 8, 1, 16, 1, 20, 1, 21, 1 }, c = { 8, 13, 16, 1, 20, 1, 21, 1 }, w = 11 }, { f = 15.3, m = { 2, 7, 1, 2, 12, 1, 23, 1 }, c = { 1, 9, 1, 8, 2, 8, 2, 9, 2, 10, 2, 11, 2, 12, 2, 13, 2, 14, 12, 3, 23, 1 }, w = 12 }, { f = 10.1, m = { 7, 3, 5, 1, 12, 1 }, c = { 5, 3, 7, 3, 7, 2, 7, 4, 12, 2 }, w = 13 }, { f = 12.9, m = { 1, 6, 2, 6, 6, 2, 5, 1 }, c = { 1, 2, 1, 4, 1, 5, 1, 3, 1, 6, 1, 7, 2, 2, 2, 3, 2, 4, 2, 5, 2, 6, 2, 7, 5, 2, 6, 3, 6, 2 }, w = 14 }, { f = 0.0, m = { 17, 1 }, c = { 17, 1 }, w = 15 } }, titleZh = "Tactyks 野队友好", codeZh = "!~MDT2~" },
    { pos = 5, community = true, source = "wago.io", author = "Salatikue", url = "https://wago.io/wbrrhOtYG", title = "Keksh", views = 122, name = "Keksh", code = "!~MDT2~", pct = 100.0, pulls = { { f = 9.9, m = { 2, 8, 1, 3, 3, 2, 4, 1, 6, 1 }, c = { 1, 13, 1, 11, 1, 12, 2, 27, 2, 28, 2, 29, 2, 31, 2, 32, 2, 33, 2, 34, 2, 30, 3, 3, 3, 4, 4, 2, 6, 4 }, w = 1 }, { f = 9.5, m = { 2, 7, 1, 2, 3, 2, 5, 1, 6, 1 }, c = { 1, 18, 1, 19, 2, 50, 2, 51, 2, 86, 2, 85, 2, 87, 2, 88, 2, 89, 3, 9, 3, 10, 5, 9, 6, 7 }, w = 2 }, { f = 8.2, m = { 2, 5, 3, 2, 6, 2, 5, 1 }, c = { 2, 54, 2, 52, 2, 53, 2, 55, 2, 56, 3, 5, 3, 6, 5, 7, 6, 15, 6, 9 }, w = 3 }, { f = 7.3, m = { 2, 9, 1, 2, 4, 1, 6, 1 }, c = { 1, 16, 1, 17, 2, 41, 2, 42, 2, 43, 2, 44, 2, 45, 2, 46, 2, 48, 2, 49, 2, 47, 4, 3, 6, 5 }, w = 4 }, { f = 1.6, m = { 2, 4, 1, 1, 13, 1, 14, 1, 15, 1 }, c = { 1, 15, 2, 38, 2, 39, 2, 37, 2, 40, 13, 1, 14, 1, 15, 1 }, w = 5 }, { f = 11.8, m = { 2, 5, 3, 2, 1, 1, 4, 1, 5, 1, 7, 1, 8, 1 }, c = { 1, 25, 2, 94, 2, 91, 2, 90, 2, 92, 2, 93, 3, 11, 3, 12, 4, 5, 5, 10, 7, 16, 8, 9 }, w = 6 }, { f = 0.0, m = { 18, 1 }, c = { 18, 1 }, w = 7 }, { f = 9.9, m = { 9, 5, 12, 2, 7, 1, 8, 1, 10, 1 }, c = { 7, 17, 8, 10, 9, 20, 9, 22, 9, 21, 9, 18, 9, 19, 10, 9, 12, 3, 12, 4 }, w = 8 }, { f = 7.4, m = { 9, 5, 8, 2, 10, 2, 12, 1 }, c = { 8, 11, 8, 12, 9, 32, 9, 33, 9, 30, 9, 39, 9, 31, 10, 10, 10, 11, 12, 5 }, w = 9 }, { f = 11.8, m = { 2, 7, 1, 2, 23, 1 }, c = { 1, 8, 1, 9, 2, 8, 2, 9, 2, 10, 2, 11, 2, 12, 2, 13, 2, 14, 23, 1 }, w = 10 }, { f = 0.0, m = { 16, 1 }, c = { 16, 1 }, w = 11 }, { f = 12.7, m = { 1, 6, 2, 6, 6, 2, 5, 1 }, c = { 1, 2, 1, 4, 1, 5, 1, 3, 1, 6, 1, 7, 2, 2, 2, 3, 2, 4, 2, 5, 2, 6, 2, 7, 5, 2, 6, 2, 6, 3 }, w = 12 }, { f = 9.9, m = { 7, 3, 5, 1, 12, 1 }, c = { 5, 3, 7, 3, 7, 2, 7, 4, 12, 2 }, w = 13 }, { f = 0.0, m = { 17, 1 }, c = { 17, 1 }, w = 14 } }, titleZh = "Keksh", codeZh = "!~MDT2~" },
