  ["voidscararena"] = {
    { pos = 1, community = true, source = "keystone.guru", author = "alexandros_theroman", url = "https://keystone.guru/route/voidscar-arena/LHXRfPr/skandar-tank-voidscar-arena-season-2-10-to-15", title = "Skandar Tank - Voidscar Arena Season 2 (+10 to +15)", views = 125619, name = "Skandar Tank - Voidscar Arena Season 2 (+10 to +15)", code = "!~MDT2~", pct = 100.0, pulls = { { f = 8.7, m = { 4, 2, 6, 2, 1, 1, 2, 1, 5, 1, 7, 1 }, c = { 1, 11, 2, 11, 4, 6, 4, 7, 5, 13, 6, 2, 6, 3, 7, 1 }, w = 1, ne = { "BIG OPENING LUST — GO RIGHT\nPull the right-side hallway into the first lieutenant and LoS casters around the corner. Lust here. Rotate kicks/stops carefully.\n\nPOLIMORPH OR CAGE: Dominated brawler, so it does not join you in this pull, but will join you during Mini-Boss for extra funnel. You can also skip Brawler entirely here if you want.", "VOIDTOUCHED MAGI = PRIORITY\nKick Shadowbolt Volley. Null Eruption targets a player with a large circle — move it away, defensive the hit, and avoid the puddle.", "SHAMANS & TOTEMS\nKick Lava Bolt when priority casts are covered. Kill/cleave Magma Totems quickly before their pulsing AoE becomes dangerous.", "BL first pull", "You can go left or right here. Right is better overall, because you can control it more.  Just make sure everyone mark one caster and kick - and that everyone INSTANTLY SWAP to Totems and kill them as priority target (or wipe)" }, nz = { "开局大波嗜血 — 走右边\n把右侧走廊拉进第一个精英，施法怪在拐角卡视角。这里开嗜血。打断/控制要轮好。\n\n变羊或牢笼：被统御的斗士，让它不加入这波，但打小 boss 时会加入，多一个顺劈目标。也可以直接跳过斗士。", "虚触法师 = 优先\n打断暗影箭雨。虚无喷发点名一人放大圈——带出去、开减伤吃伤害、躲开水池。", "萨满 & 图腾\n优先读条都覆盖到时再打断熔岩箭。熔岩图腾要快速击杀/顺劈掉，别等它脉冲 AOE 变危险。", "第一波开嗜血", "这里走左走右都行。总体右边更好，更可控。确保每人标记一个施法怪打断——所有人立刻转火图腾优先击杀（不然灭团）" }, np = { 283.5, 491.3, 332.1, 426.8, 321.3, 480.3, 205.0, 458.8, 200.3, 513.8 } }, { f = 5.4, m = { 10, 1 }, c = { 10, 1 }, w = 2, ne = { "RAJ’KESS — KILL THE ORBS!\nSpread for Forked Lightning. When 3 Orbs of Disruption spawn, hard swap immediately — a completed cast gives the group a huge Haste reduction.\nRAJ’KESS — THUNDERING STORM\nLong heavy party-damage channel + swirlies. Healing CD + personals on higher keys. Keep moving while maintaining DPS." }, nz = { "拉杰克斯 — 打球！\nForked Lightning 散开。3 个 Orbs of Disruption 出现时立刻硬转火——读条完成全队会被大幅降急速。\n拉杰克斯 — 雷鸣风暴\n长时间高额全队伤害引导 + 旋涡。高层要开治疗大招 + 个人减伤。边走边保持输出。" }, np = { 288.6, 324.8 } }, { f = 6.9, m = { 1, 3, 2, 3, 3, 3, 4, 3 }, c = { 1, 1, 1, 2, 1, 3, 2, 1, 2, 2, 2, 3, 3, 1, 3, 2, 3, 3, 4, 1, 4, 2, 4, 3 }, w = 3, ne = { "TAZ’RAH — PLAY THE EDGE\nLoosely spread for Nether Dash and NEVER overlap lines. Place Umbral Rupture pools around the outside and rotate clockwise/counter-clockwise. Aim the lines against the wall if you can." }, nz = { "塔兹拉尔 — 打边缘\n空灵冲刺松散站位，线绝对不要重叠。幽影破裂的水池放外圈，顺时针/逆时针转。能的话把线对着墙。" }, np = { 221.1, 220.6 } }, { f = 7.2, m = { 2, 2, 4, 2, 11, 1, 12, 1, 13, 1 }, c = { 2, 4, 2, 5, 4, 4, 4, 5, 11, 1, 12, 1, 13, 1 }, w = 4, ne = { "PROTECTIVE TURTLE\nMove the pack OUT of Shell Guard so mobs do not gain its damage reduction. When the shield drops, cleave the Turtle during its vulnerable window." }, nz = { "充满保护欲的乌龟\n把这波怪拉出 Shell Guard，别让它们吃到减伤。盾掉了就趁易伤窗口顺劈乌龟。" }, np = { 154.8, 156.5 } }, { f = 7.3, m = { 1, 2, 3, 2, 14, 1, 15, 1, 16, 1 }, c = { 1, 4, 1, 5, 3, 4, 3, 5, 14, 1, 15, 1, 16, 1 }, w = 5, ne = { "WAIT FOR TANK TO SECURE AGGRO, especially BDK and VDH!", "FIRST ARENA — TANK DANGER\nFeral Saberons can stack nasty bleeds. Watch tank debuffs, use bleed removals/externals, and dispel the dangerous magic tank debuff when available", "BRUTOK — AIM CHARGE AT WALL\nTank Brutok close to a wall and point Smashing Charge directly into it to shorten movement and trigger the stun. Defensive for Head Bash.\n\nFinish Chitigoth first and then pull Brutok - overlap is dangerous!" }, nz = { "等坦克稳住仇恨，尤其是血 DK 和复仇 DH！", "第一个竞技场 — 坦克危险\n狂野的刃牙虎人会叠很恶心的流血。注意坦克 debuff，用去流血/外部减伤，危险的坦克魔法 debuff 能驱散就驱散", "布鲁托克 — 冲锋对墙\n坦克贴墙拉布鲁托克，把 Smashing Charge 直接对准墙，缩短位移并触发眩晕。头槌重击开减伤。\n\n先打完几丁高斯再拉布鲁托克——重叠很危险！" }, np = { 178.6, 107.0, 222.3, 104.3, 195.1, 94.7 } }, { f = 11.4, m = { 21, 1, 17, 1, 18, 1, 6, 1 }, c = { 21, 1, 17, 1, 18, 1, 6, 4 }, w = 6, ne = { "You can chain when Harrower goes to 40% health.", "SKIP: you can skip this pack with shroud or invisib or other skips.  Can get more percentage from final area." }, nz = { "掠心者到 40% 血时可以连拉。", "跳过：这波可以用暗影斗篷、隐形或其他方式跳过。最后区域能拿更多进度。" }, np = { 117.2, 222.5, 187.6, 288.2 } }, { f = 14.1, m = { 5, 1, 6, 1, 8, 1, 21, 1 }, c = { 5, 8, 6, 6, 8, 3, 21, 4 }, w = 7, ne = { "You must kill / break the shield of Brutal Overseer as fast as possible!" }, nz = { "鲁莽监督者的盾必须尽快打掉 / 打破！" }, np = { 100.5, 198.8 } }, { f = 0.0, m = { 28, 2, 26, 1 }, c = { 26, 1, 28, 1, 28, 2 }, w = 8, ne = { "ATROXUS — ADD = HARD PRIORITY\nPlay near the next side platform. When Toxic Creeper spawns, EVERYONE swaps immediately. Tank should kite it — do not let Sickening Bite stacks build." }, nz = { "阿特洛苏斯 — 小怪 = 绝对优先\n靠近下一个侧平台打。剧毒蠕行者出现时所有人立刻转火。坦克要风筝它——别让 Sickening Bite 层数叠起来。" }, np = { 661.6, 471.0 } }, { f = 10.8, m = { 23, 10, 2, 2, 3, 2, 17, 2, 24, 2, 22, 1 }, c = { 2, 9, 2, 10, 3, 7, 3, 8, 17, 16, 17, 17, 22, 3, 23, 51, 23, 52, 23, 53, 23, 54, 23, 55, 23, 56, 23, 57, 23, 58, 23, 59, 23, 60, 24, 5, 24, 6 }, w = 9, ne = { "CHARONUS — ONE ORB PER DPS\nBait 3 clean Unstable Singularities. Each DPS takes one Gravitic Orb into a different Singularity. Tank aims Dark Waves away; Void Cascade target runs sideways with speed." }, nz = { "煞戎努斯 — 每个 DPS 一个球\n引 3 个干净的 Unstable Singularities。每个 DPS 带一个引力宝珠进不同的 Singularity。坦克把暗影浪潮朝外放；虚空奔涌点名的人带加速往侧面跑。" }, np = { 640.7, 192.3 } }, { f = 12.2, m = { 17, 2, 18, 2, 24, 2, 1, 1, 3, 1, 5, 1, 6, 1, 22, 1 }, c = { 1, 8, 3, 6, 5, 11, 6, 12, 17, 14, 17, 15, 18, 13, 18, 14, 22, 1, 24, 1, 24, 2 }, w = 10 }, { f = 5.7, m = { 23, 10, 17, 2, 1, 1, 2, 1, 5, 1, 18, 1 }, c = { 1, 7, 2, 6, 5, 4, 17, 12, 17, 13, 18, 8, 23, 31, 23, 32, 23, 33, 23, 34, 23, 35, 23, 36, 23, 37, 23, 38, 23, 39, 23, 40 }, w = 11 }, { f = 10.3, m = { 1, 2, 17, 2, 24, 2, 18, 1, 22, 1, 6, 1 }, c = { 1, 9, 1, 10, 17, 18, 17, 19, 18, 15, 22, 2, 24, 3, 24, 4, 6, 14 }, w = 12, ne = { "FINAL TRASH — ONE BRUTALIZER AT A TIME\nDreadbellow = party DoT. Brutalize = heavy tank channel. Stop Mending Void and avoid stacking multiple dangerous lieutenants together." }, nz = { "最后的小怪 — 一次只拉一个残虐者\n恐惧咆哮 = 全队 DoT。残杀 = 坦克高额引导。打断愈体虚空，别把多个危险精英叠一起。" }, np = { 615.1, 330.6 } } }, titleZh = "Skandar 坦克 - 虚空之痕竞技场 第二赛季（+10~+15 层）", codeZh = "!~MDT2~" },
