do
  local classID = UnitClass and select(3, UnitClass("player"))   -- ⛔ 别写 `local _, _, c = UnitClass and UnitClass()`：and 只留第一个返回值
  if classID and GetNumSpecializationsForClassID and GetSpecializationInfoForClassID then
    local keep, n = {}, 0
    for i = 1, GetNumSpecializationsForClassID(classID) or 0 do local id = GetSpecializationInfoForClassID(classID, i); if id then keep[id] = true; n = n + 1 end end
    if n > 0 then
      for _, T in ipairs({ GearInsightMdtSpecRoutes, GearInsightMdtSpecRoutes12 }) do
        for sid in pairs(T or {}) do if not keep[sid] then T[sid] = nil end end
      end
    end
  end
end
do
  local zh = GetLocale and (GetLocale() == "zhCN" or GetLocale() == "zhTW")
  for _, lst in pairs(GearInsightMdtCommunityRoutes) do
    for _, e in ipairs(lst) do
      if zh and e.titleZh then e.title = e.titleZh; e.name = e.titleZh end
      if zh and e.codeZh then e.code = e.codeZh end
      for _, p in ipairs(e.pulls or {}) do p.nt = (zh and p.nz) or p.ne; p.nz, p.ne = nil, nil end
    end
  end
end
